programs.sol:
"""A small lexical detector for exceptions, qualifications, and '-cept-' words.

The strongest negative responses are 'except' and 'unless'. Catch/accept,
receiving/intercepting vocabulary, and split '-cept-' endings also respond.
A few exclusion phrases respond on their second word. We remember just the
previous token (resetting at document boundaries), not parse the sentence.
"""
READS = ()

# Other languages' exclusion and receiving words.
TRANSLATIONS = {
    '除': -1.0,       # remove / except
    '除了': -1.5,     # except / besides
    '除非': -3.9,     # unless
    '接': -1.1,       # receive / connect
    '接收': -1.05,    # receive
    '接受': -0.65,    # accept
    '截': -2.0,       # intercept / cut
    '拦截': -1.65,    # intercept
    'إلا': -2.25,     # except
}
EXCEPT_PHRASES = {
    'for': -2.5, 'that': -1.45, 'in': -0.8, 'the': -0.7,
    'to': -0.6, 'when': -0.53, 'if': -0.55, 'as': -0.4, 'at': -0.27,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word, prev = token.lower(), previous.strip().lower()
    value = 0.0
    if word == 'except':
        value = -8.9 if token[0].isupper() else (
            -8.3 if raw.startswith(' ') else -7.7)
    elif word == 'unless':
        value = -4.5 if raw.startswith(' U') else -3.85
    elif word == 'catch':
        value = -3.05 if '}' in previous else -2.4
    elif word in {'catches', 'catching'}:
        value = -1.55
    elif word in {'caught', 'catcher', 'catchers'}:
        value = -1.15
    elif word in {'accept', 'accepts'}:
        value = -1.4
    elif word == 'accepting':
        value = -0.75
    elif word in {'accepted', 'acceptance'}:
        value = -0.4
    elif word in {'acceptable', 'unacceptable'}:
        value = -1.0
    elif word == 'intercept':
        value = -4.2
    elif word in {'intercepted', 'interceptor', 'interceptors', 'interceptions'}:
        value = -1.8
    elif word == 'recept':
        value = -2.8
    elif word in {'receptor', 'receptors', 'reception', 'receptions', 'inception'}:
        value = -1.2
    elif word in {'receiver', 'receivers'}:
        value = -0.6
    elif word in {'cept', 'cepts'}:
        if prev.endswith('ex'):
            value = -9.0 if token.isupper() else -7.6
        elif prev.endswith('con'):
            value = -0.65
        elif prev.endswith('pre'):
            value = -3.5
        elif prev.endswith('inter'):
            value = -5.45
        elif prev.endswith('per'):
            value = -2.5
        else:
            value = -4.8
    elif word in {'ception', 'ceptions'}:
        value = -0.55 if prev.endswith(('con', 'per')) else -2.2
    elif word in {'ceptor', 'ceptors', 'percept'}:
        value = -1.65
    elif word in {'rece', 'cerpt', 'excerpt'}:
        value = -1.2
    elif word == 'exception':
        value = -0.8 if token[0].isupper() else -1.2
    elif word == 'exceptions':
        value = -1.1
    elif word == 'until' or word in {'excluding', 'besides', 'albeit'}:
        value = -0.85
    elif word == 'especially':
        value = -0.45
    elif word == 'кроме':
        value = -0.35 if token[0].isupper() else -1.95
    else:
        value = TRANSLATIONS.get(word, 0.0)

    if prev == 'except' and word in EXCEPT_PHRASES:
        value = EXCEPT_PHRASES[word]
    elif (prev, word) == ('other', 'than'):
        value = -1.12
    elif word == 'of' and prev in {'exception', 'intercept'}:
        value = -1.25
    return (doc, raw), float(value)

programs.luna:
"""A lexical sketch of exception and boundary language.

The strongest harvested examples are negative on 'except' and 'catch', with
smaller signals on exception-related and clause-boundary words. This predicts
those readable surface cues and leaves other activations at zero.
"""
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    word = word.strip(".,;:!?()[]{}\"'")

    if word == "except" or word.startswith("except-"):
        return None, -7.0
    if "exception" in word:
        return None, -1.0
    if word == "catch" or word == "catch".capitalize().lower():
        return None, -2.5
    if "catching" in word:
        return None, -0.7
    if "accept" in word:
        return None, -1.5
    if word == "unless":
        return None, -4.0
    if word == "until":
        return None, -0.8
    if word == "than":
        return None, -0.8
    if "especially" in word:
        return None, -0.7
    return None, 0.0

programs.sol:
"""Approximate a signed temporal-word signal from token spelling and context.

Before, when, while, and after are strongly positive; time units and
calendar names are mostly negative. Recent temporal vocabulary makes the
response less positive, distinguishing 'three days after' from 'after we
left'. Three recency memories weaken with each token and reset for a new
document. Case, a few preceding words, and document-start position refine
these estimates. Unrecognized tokens give zero. This is a lexical
approximation, not a full parser or an account of every small response.
"""
from math import exp

READS = ()

CONNECTIVES = {
    'before': 1.32, 'when': 1.00, 'while': 0.97, 'whilst': 1.00,
    'after': 0.73, 'during': 0.45, 'whenever': 0.51,
    'whereas': 0.22,
}
# Units, calendar vocabulary, and temporal modifiers.
TIME_WORDS = {
    'time': -0.06, 'times': -0.15, 'day': -0.42, 'days': -0.42,
    'week': -0.29, 'weeks': -0.26, 'month': -0.46, 'months': -0.16,
    'year': 0.02, 'years': 0.07, 'hour': -0.16, 'hours': -0.18,
    'minute': -0.09, 'minutes': -0.05, 'second': 0.00, 'seconds': -0.12,
    'morning': -0.33, 'afternoon': -0.65, 'evening': -0.35,
    'night': -0.23, 'midnight': -0.67, 'noon': -0.78,
    'calendar': -0.45, 'birthday': -0.40, 'anniversary': -0.90,
    'century': -0.22, 'semester': -0.34, 'weekend': -0.28,
    'elapsed': -1.19, 'ago': -0.31, 'subsequent': -0.23,
    'thereafter': -0.35, 'eventually': -0.24, 'earliest': -0.40,
    'latest': -0.21, 'now': -0.09, 'then': -0.05,
    'period': -0.13, 'periods': -0.36, 'daily': -0.19,
    'date': 0.33, 'dates': 0.41, 'dated': 0.44,
}
MONTHS = set('january february march april may june july august '
             'september october november december'.split())
WEEKDAYS = set(
    'monday tuesday wednesday thursday friday saturday sunday'.split()
)
TIME_QUANTITIES = set('time times day days week weeks month months year years '
                      'hour hours minute minutes second seconds period periods '
                      'night morning afternoon evening century centuries'.split())
TRANSLATED = {
    'cuando': 0.42, 'quando': 0.28, 'khi': 0.49, 'когда': 0.41,
    'после': 0.39, 'après': 0.44, 'mientras': 0.49, 'lors': 0.50,
    'いつ': 0.64, '的时候': 0.89, '的時候': 0.95, '时候': 0.61,
    '时': 0.42, '時': 0.34, '日': -0.69, '月': -0.40,
    '上午': -0.89, '下午': -0.75, '晚上': -0.44,
}


# Each memory is the proximity of a recent quantity, calendar term, or
# event-linking word. Every intervening token weakens it by 15%.
CALENDAR_CUES = (MONTHS - {'may'}) | WEEKDAYS | {
    'calendar', 'anniversary', 'birthday', 'thanksgiving', 'christmas',
    'date', 'dates', 'dated',
}
VAGUE_QUANTITIES = {'few', 'many', 'some', 'several', 'any'}
NUMBER_WORDS = set(
    'one two three four five six seven eight nine ten each per'.split()
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    spelling = token.strip().lstrip('_-./(')
    word = spelling.lower()
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
        quantities, calendar, linking = 0.0, 0.0, 0.0
    else:
        _, position, previous, quantities, calendar, linking = carry

    if word in CONNECTIVES:
        value = CONNECTIVES[word]
        value -= 0.75 * quantities + 0.44 * calendar + 0.31 * linking
        value -= 0.41 * exp(-position / 2)
        if previous in {'a', 'an'}:
            value -= 0.15
        if previous in {'long', 'shortly', 'immediately'}:
            value -= 0.31
        if spelling[:1].isupper():
            value += {
                'before': 0.10, 'while': -0.07, 'during': -0.13,
            }.get(word, 0)
    elif word in TIME_WORDS:
        value = TIME_WORDS[word] + 0.06
        value -= 0.46 * quantities + 0.61 * calendar + 0.28 * linking
        value -= 0.50 * exp(-position / 2)
        if word == 'date' and spelling[:1].isupper():
            value += 0.23
        if word == 'time':
            if previous in {'in', 'over'}:
                value += 0.33
            elif previous in {'long', 'short', 'of', 'first', 'last', 'next'}:
                value -= 0.25
        if word == 'day' and previous in {'one', 'some', 'all'}:
            value += 0.33
        if previous in VAGUE_QUANTITIES:
            value += 0.23
        if previous in {'last', 'next', 'previous', 'past', 'recent'}:
            value -= 0.13
        if previous in NUMBER_WORDS:
            value += 0.12
        if spelling[:1].isupper() and word in TIME_QUANTITIES:
            value -= 0.20
    elif word in MONTHS or word in WEEKDAYS:
        value = -0.28 if word in MONTHS else -0.48
        if word == 'may':
            value = -0.04
        value += 0.08 - 0.26 * quantities - 0.74 * calendar - 0.16 * linking
        value -= 0.58 * exp(-position / 2)
        if previous in {'in', 'on'}:
            value += 0.27
    elif word in TRANSLATED:
        value = TRANSLATED[word] + 0.01 - 0.17 * exp(-position / 2)
    else:
        value = 0.0

    quantities = max(float(word in TIME_QUANTITIES), 0.85 * quantities)
    calendar = max(float(word in CALENDAR_CUES), 0.85 * calendar)
    linking = max(float(word in CONNECTIVES), 0.85 * linking)
    carry = (doc, position + 1, word, quantities, calendar, linking)
    return carry, float(value)

"""Detect backslash markers, not the letters of escape sequences.

A backslash at the end of a token is the main signal. Doubled backslashes
are stronger; preceding whitespace or punctuation modulates the signal.
Escapes already fused to their following character are mostly quiet.
The small background activations on ordinary words are not modeled.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    before = token.rstrip("\\")
    slashes = len(token) - len(before)
    if not slashes:
        if "\\" in token and token.strip() in {r"\n", r"\t", r'\"'}:
            return None, -0.03
        return None, 0.001

    attached = before.strip()
    if slashes >= 2:
        value = 1.08 - (0.06 if before.isspace() else 0.0)
        if attached.endswith("}"):
            value -= 0.19
        if slashes == 3:
            value = 0.73
        elif slashes >= 4:
            value = 1.30
        return None, value

    if not attached:
        return None, 0.58 if before else 0.44
    last = attached[-1]
    if "\\" in attached:
        value = 0.24
    elif last == "{":
        value = 0.07 if before.startswith(" ") else -0.03
    elif last == "(":
        value = 0.19 if before.startswith(" ") else 0.04
    elif last == "}":
        value = 0.17
    elif last in "[]":
        value = 0.27 if last == "]" else 0.16
    elif last in "$=+-*^_|":
        value = 0.10
    elif last in "\"`":
        value = 0.26
    elif last == ":" and not attached.endswith("):"):
        value = 0.49
    elif last == ".":
        value = 0.43
    elif last == ",":
        value = 0.39
    else:
        value = 0.35
    return None, value

programs.haiku:
"""Layer-0 MLP down-projection unit 5059: a 'stray backslash' detector.

The unit reads the token just read and fires when that token ends in a literal
backslash character. It is strongest for a backslash typed as ordinary text or code
(a doubled backslash, or " \\" after a space), and weaker when the backslash closes
a bracket or punctuation inside LaTeX math. All other tokens predict 0.
"""

READS = ()


def _strength(token, in_math):
    if not token.endswith("\\"):
        return 0.0
    if token.endswith("\\\\"):
        return 1.1
    if token == " \\":
        return 0.5 if in_math else 0.75
    if token == "\\":
        return 0.37 if in_math else 0.53
    if in_math:
        return 0.1  # e.g. ")\\" or "}\\" inside an equation
    return 0.3


def step(carry, prefix, upstream):
    text = "".join(prefix.token_strings[-30:-1])
    in_math = "$" in text or "\\" in text[-12:]
    return None, float(_strength(prefix.token_strings[-1], in_math))

programs.luna:
"""Predict a sparse backslash signal, with a stronger estimate for doubled marks."""
READS = ()
CLOSERS = set(".,;:!?)]}'\"'")

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if not token.endswith("\\"):
        return None, 0.0

    before = token[:-1]
    doubled = "\\\\" in token
    if doubled:
        before = before.replace("\\", "")
    before = before.strip()
    if any(character.isalnum() for character in before):
        return None, 0.0
    if any(character not in CLOSERS for character in before):
        return None, 0.0

    if doubled:
        return None, 1.0
    if before.endswith("}"):
        return None, 0.20
    return None, 0.45

programs.haiku:
"""Contrast connectives after negation: layers.0.mlp.down_proj:5060.

This component writes a 'contrast / alternative' signal into the residual stream. It is
strongest on the connective that follows a negated clause, as in "not only X *but* also Y",
"not X *or* Y", "cannot help *but*", "nothing *but*", "no X *unless*". It fires weakly on
the same connectives in ordinary prose, and it fades as the negation gets further away.

Program: find each token of a contrast class, and give it a value that is larger the
closer the most recent negation word is (same document only).
"""

import math

READS = ()

# Connectives that set up an alternative or exception.
CONNECTIVES = {"but", "or", "yet", "nor", "unless"}
# Words that often carry the same contrast or exception sense, weaker.
PARTICLES = {"only", "still", "than", "except", "anything", "nothing", "much", "alternatively"}
# Smaller, looser set that adds a little.
SOFT = {"also", "even", "just", "rather", "else", "too", "any", "instead"}
NEGATIONS = {
    "not", "no", "never", "cannot", "neither", "without", "none", "nobody", "nowhere",
    "nothing", "nor",
}

DECAY = 12.0   # tokens over which the negation's pull fades
FLOOR = 0.3    # strength of a connective with no recent negation


def _is_negation(word):
    return word in NEGATIONS or word.endswith("n't")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    pos = prefix.position
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "neg_at": None}
    word = prefix.token_strings[-1].strip().lower()

    if carry["neg_at"] is not None:
        distance = pos - carry["neg_at"]
        pull = math.exp(-(distance - 1) / DECAY)
    else:
        pull = 0.0
    if word in CONNECTIVES:
        weight = 1.0
    elif word in PARTICLES:
        weight = 0.5
    elif word in SOFT:
        weight = 0.2
    else:
        weight = 0.0
    value = weight * (FLOOR + pull)

    if _is_negation(word):
        carry = {"doc": doc, "neg_at": pos}
    return carry, value

programs.luna:
"""Use the article spelling as a cue: space-prefixed 'an' and 'An'
produce a strong positive response; bare 'an' and space-prefixed 'a'
get smaller responses. All other tokens get zero."""
READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in (" an", " An", "An"):
        return None, 3.6
    if token == "an":
        return None, 0.54
    if token == " a":
        return None, 0.10
    return None, 0.0

"""Estimate this component with a small lexical rule.

It is usually quiet, but often responds positively to the English “of” and
French “de”. The response to “of” is especially large after nouns naming a
quantity, interval, endpoint, or position, as in “number of” and “end of”.
"""

READS = ()

OF_TOKENS = {" of", "of"}
DE_TOKENS = {" de", "de"}

# These nouns commonly introduce a quantity, interval, endpoint, or position:
# “end of”, “rate of”, “number of”, and similar phrases.
MEASURE_OR_BOUNDARY_HEADS = {
    "age", "amount", "beginning", "date", "direction", "duration",
    "end", "front", "length", "middle", "midpoint", "number", "out",
    "period", "point", "rate", "range", "side", "time", "year",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in DE_TOKENS:
        return None, 0.6
    if token not in OF_TOKENS:
        return None, 0.0
    if (
        len(prefix.token_strings) > 1
        and prefix.document_ids[-2] == prefix.document_ids[-1]
    ):
        head = prefix.token_strings[-2].strip().casefold()
        if head in MEASURE_OR_BOUNDARY_HEADS:
            return None, 3.0
    return None, 0.9

programs.sol:
"""Predict the component's main operator/separator response.

Use token spelling and spacing to recognize bars, Boolean operators,
ampersands and angle operators. A fading count weakens repeated bars.
The last 160 characters give rough tag/type-bracket context; this is a
heuristic, not a parser. LaTeX bar names, parallel and elif also respond.
Reset context at document boundaries. Other tokens predict zero, leaving
small, scattered lexical activations unmodelled.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0)
    _, before, recent_bars = carry
    token = prefix.token_strings[-1]
    s = token.strip()
    spaced = token.startswith(' ')
    newline = '\n' in token
    open_angle = before.rfind('<') > before.rfind('>')
    previous = before[-1:]
    value = 0.0

    if s in ('||', '&&'):
        value = 1.34 if spaced else (1.04 if s == '||' else 1.25)
        if newline:
            value = 1.0
    elif s == '|':
        value = 0.30 + 0.15 * spaced + 0.68 / (1.0 + recent_bars)
        value -= 0.32 * newline
        if previous.isdigit():
            value -= 0.13
        elif previous and previous.isspace():
            value -= 0.10
    elif '|' in s and all(c in '|(){}[]"\'\\' for c in s):
        value = 0.73
    elif s == '>&':
        value = 1.10
    elif s in ('&', '＆'):
        value = 0.83 if spaced else 0.70
        if newline:
            value = 0.58
    elif '&' in s and not s.startswith('<|'):
        value = 0.33 if '#' in s else 0.60
        if s == '(&':
            value = 0.46
    elif s == '>':
        value = 0.91 if spaced else (0.07 if open_angle else 0.96)
        if newline:
            value = 0.28 if spaced else -0.05
    elif s == '<':
        if before.endswith('include'):
            value = 0.20
        elif re.search(r'<[/!]?[A-Za-z][^<>]*>', before):
            value = 0.0
        elif not previous or previous.isspace():
            value = 0.25
        else:
            value = 0.70 if spaced else 0.32
    elif s in ('<=', '>=', '<>'):
        value = 0.29 if s == '<=' else 0.37
    elif s == '>>':
        value = 0.56 if spaced else (-0.20 if open_angle else 0.65)
    elif s in ('≤', '≥', '‹', '›', '∣'):
        value = 0.27
    elif s in ('│', '┃'):
        value = 0.47
    elif s in ('vert', 'Vert'):
        value = 0.82 if re.search(r'\\[lr]?$', before) else 0.24
    elif s == 'parallel':
        value = 0.42
    elif s == 'elif':
        value = 0.43

    bars = 0 if token.startswith('<|') else token.count('|')
    carry = (doc, (before + token)[-160:], 0.95 * (recent_bars + bars))
    return carry, float(value)

programs.luna:
"""Predict operator-like activations from the current token alone.

Paired Boolean marks get the strongest pulse, pipes a smaller one, and
comparison or markup punctuation a weaker one; other tokens get zero.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "&&" in token or "||" in token:
        value = 0.70
    elif "|" in token:
        value = 0.28
    elif any(char in token for char in "<>=›&"):
        value = 0.16
    else:
        value = 0.0
    return None, value

programs.sol:
"""Approximate surface-pattern explanation, calibrated on training examples.

Negative reference signals are strongest in comparisons such as 'than those',
with weaker responses after 'as', 'like', and 'unlike'. Capitalization and
simple grammatical contexts adjust the reference-word background. Selected
temporal and ordinal words are mildly negative; 'another', 'different', and
lowercase assurance words are positive. The '-value' suffix is positive,
especially in 'key-value'. Small side rules cover 'shown/measured in',
'located/situated/living in', and the literal escaped tab marker.

This is not a parser: it matches whole decoded tokens, usually case-folded
and stripped. It remembers just one token and resets at document boundaries.
Unmatched tokens get -0.001; most diffuse activation is left unexplained.
"""
READS = ()

# Demonstratives and indefinite reference words: background, then comparison.
REFERENCES = {
    'those': (-0.18, -0.67),
    'others': (-0.07, -0.57),
    'ones': (-0.14, -0.55),
    'one': (-0.013, -0.45),
    'any': (0.022, -0.55),
    'anyone': (0.00, -0.50),
    'anything': (0.045, -0.34),
    'either': (-0.05, -0.50),
    'other': (-0.015, -0.36),
    'that': (-0.012, -0.30),
    'this': (-0.002, -0.14),
}
TEMPORAL = {'previous', 'previously', 'past', 'future', 'final'}
ORDINALS = {'first', 'second', 'third', 'fourth', 'fifth'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text = token.strip()
    word = text.lower()
    titled = text.istitle()
    value = -0.001
    if word in REFERENCES:
        background, comparison = REFERENCES[word]
        value = background
        if previous == 'than':
            value = comparison
        elif previous in {'as', 'like', 'unlike'}:
            scale = 0.55 if previous == 'as' else 0.8
            value += scale * (comparison - background)
        elif titled:
            if word in {'one', 'any', 'anyone', 'anything'}:
                value = 0.17 if word == 'any' else 0.11
            elif word == 'that':
                value = 0.058
            elif word in {'those', 'others'}:
                value = -0.025
            elif word == 'this':
                value = -0.02
        elif word == 'any' and previous == 'without':
            value = -0.23
        elif word == 'one' and previous in {'only', 'just'}:
            value = -0.17 if previous == 'only' else -0.12
        elif word == 'one' and previous in {'is', 'was'}:
            value = 0.085
        elif word == 'that' and previous in {'so', 'fact'}:
            value = 0.085
    elif word in {'another', 'different'}:
        value = 0.068 if word == 'another' else 0.046
        if word == 'another' and titled:
            value = 0.16
    elif word in TEMPORAL:
        value = -0.09
    elif word in ORDINALS:
        value = 0.015 if word == 'first' and titled else -0.03
    elif token == '-value':
        value = 0.60 if previous == 'key' else 0.17
    elif word in {'correct', 'sure'} and text.islower():
        value = 0.095
