import re

READS = ()

# Lexical fields, with stronger values for collective/plural concepts.
FIELDS = (
    # Taxonomic kinds.
    (-0.76, {'species', 'interspecies', 'intraspecies', '物种', '物種'}),
    (-1.0, {'subspecies'}),
    # Human collectives and cultures.
    (-0.90, {'humanity', 'mankind', '文明'}),
    (-0.70, {'civilization', 'civilizations', '民族'}),
    (-0.90, {'nations'}),
    (-0.48, {'cultures', 'economies', 'societies', 'peoples'}),
    # Inner life and intelligence.
    (-0.95, {'consciousness'}),
    (-0.45, {'意识', '意識', '生命', '人类', '人類'}),
    (-0.74, {'soul', 'souls'}),
    (-0.55, {'intelligence'}),
    (-0.42, {'openai'}),
    (-0.48, {'intelligent', 'sentient', 'conscious', 'creature', 'creatures'}),
    (-0.30, {'brain', 'brains', 'intellect', 'conscience', '智能', '大脑', '腦'}),
    (-0.25, {'artificial', 'ai', 'humans', 'race', 'races', 'racial'}),
    # Weaker responses to existence, social structures and related vocabulary.
    (-0.28, {'existence', 'creation', 'creations', 'majority', 'populations',
             'organism', 'organisms'}),
    (-0.20, {'religion', 'religions', 'society', 'communities',
             'republic', 'kingdom', 'spirit', 'spirits', '生物'}),
    (-0.35, {'国家', '國家'}),
    (-0.16, {'culture', 'economy', 'minority', 'biology', 'personality'}),
    (-0.06, {'human', 'country', 'people', 'life', 'world', 'body', 'population'}),
)
LEXICON = {word: value for value, words in FIELDS for word in words}
ANIMATE = {'human', 'living', 'sentient', 'spiritual', 'intelligent',
           'conscious', 'earthly', 'divine'}
PASSIVE = {'is', 'are', 'was', 'were', 'be', 'been', 'after', 'before',
           'while', 'without', 'from', 'to'}
REGIONAL = {'european', 'western', 'eastern', 'asian', 'african', 'american',
            'foreign', 'advanced', 'developed', 'emerging'}
CONTRAST = {'other', 'different', 'independent', 'extinct', 'human'}
LIVING_SYSTEMS = {'intelligent', 'ai', 'social', 'biological', 'bodily',
                  'living', 'nervous', 'doctrinal', 'sociotechnical'}
ENGINEERED = {'delivery', 'control', 'retrieval', 'transmission', 'cooling',
              'management', 'safety', 'pipe'}


