    if raw.isascii() and raw.isalpha():
        if not token[0].isspace() and same:
            fragment = (fragment + word)[-40:]
        else:
            fragment = word
        if fragment in LEXICON or fragment in {'mind', 'minds', 'species'}:
            word = fragment
    else:
        tail = re.search(r'[a-z]+$', word)
        fragment = tail[0] if tail else ''
    if word == 'ai' and token.strip() != 'AI':
        word = ''
    value = LEXICON.get(word, 0.003)

    if word == 'species':
        if not token.startswith(' ') and raw.lower() == 'species':
            value = -0.48
        elif previous in CONTRAST:
            value = -1.02
    elif word == 'nation':
        value = -0.35 if token.strip()[0].isupper() else -0.55
        if previous in REGIONAL or previous in {'whole', 'every', 'mighty'}:
            value -= 0.28
    elif word == 'countries':
        value = -0.43
        if previous in REGIONAL or previous in {'other', 'different'}:
            value = -0.74
        elif previous.isdigit() or previous == '+':
            value = -0.28
    elif word in {'being', 'beings', '-being'}:
        value = -0.95 if word == 'beings' else -0.23
        if previous in ANIMATE:
            value = -1.03
        elif previous in PASSIVE and word == 'being':
            value = -0.11
        elif previous == 'currently':
            value = 0.08
        elif previous in {'of', 'into'}:
            value = -0.42
    elif word in {'mind', 'minds'}:
        value = -0.52
        if previous == 'in':
            value = -0.13
        elif previous in {'never', "'t", '’t'}:
            value = -0.25
    elif word in {'union', 'unions'}:
        value = -0.15
        if previous == 'soviet':
            value = -0.85
