programs.haiku:
"""Layer-0 MLP down-projection, component 5066: a weak, token-level feature.

What it does: it predicts the component's activation from the surface form of the
current token alone (no context, no state). Each token is put in one plain category:

  * word groups with a clear meaning, checked first:
      - pronouns addressing or describing people ("you", "your", "we", "they", ...): small positive
      - organisation and authority words ("organization", "authorities", "police",
        "money", ...): clearly negative
      - code member names and braces (".addEventListener", ".getItem", "{", ...): negative
  * otherwise, the kind of characters the token holds: Latin letters, CJK, other
    alphabets, digits, punctuation, special tags, whitespace, and whether the token
    starts a word (a leading space).

Each category predicts the average activation measured on training text.

How well it fits: about 0.5% of the variance on held-out text. The component is not
explained by any concept here: its activation is a lexical effect spread over thousands
of different tokens. A full token-to-value table would explain far more, but is a list
of arbitrary ids, so it is not used.
"""

import unicodedata

READS = ()  # reads no other component

PRONOUNS = {" you", " your", " yours", " we", " our", " us", " I", " me", " my",
            " they", " them", " their", "'m", " am", "我们", "他们", "ваш"}
ORGANISATION = {" organization", " organizations", " organizational", " authorities",
                " authority", " police", " hierarchy", " money", " system",
                " technologies", " year", " years", " amount"}
CODE = {".addEventListener", ".getItem", ".js", ".LogError", "ReadOnly", ".Collectors",
        "/workspace", "{", "}", "import"}

# Average activation per category, measured on training text.
MEANS = {
    "pronoun": 0.0092, "org": -0.0437, "code": -0.0220,
    "space": 0.0006, "tag": 0.0064, "digit": 0.0012, "latin": -0.0012,
    "latin word": -0.0005, "cjk": -0.0014, "cjk word": 0.0368, "alpha": 0.0077,
    "alpha word": 0.0055, "mixed": 0.0004, "mixed word": 0.0046, "punct": -0.0005,
    "punct word": 0.0019,
}


def category(token: str) -> str:
    """The category of one token, decoded alone."""
    if token in PRONOUNS:
        return "pronoun"
    if token in ORGANISATION:
        return "org"
    if token in CODE:
        return "code"
    core = token.strip()
    if not core:
        return "space"
    if core.startswith("<") and core.endswith(">"):
        return "tag"
    kinds = set()
    for ch in core:
        if ch.isdigit():
            kinds.add("digit")
        elif ch.isalpha():
            name = unicodedata.name(ch, "")
            if any(k in name for k in ("CJK", "HIRAGANA", "KATAKANA", "HANGUL")):
                kinds.add("cjk")
            elif ch.isascii():
                kinds.add("latin")
            else:
                kinds.add("alpha")
        else:
            kinds.add("punct")
    kind = kinds.pop() if len(kinds) == 1 else "mixed"
    return kind + (" word" if token.startswith(" ") else "")


def step(carry, prefix, upstream):
    """The component's activation at this position: the category's average."""
    return carry, MEANS.get(category(prefix.token_strings[-1]), 0.0)

