    long_word = word.isalpha() and len(word) >= 4
    acronym = word.isalpha() and word.isupper() and len(word) >= 2

    value = -0.0014
    if token == "<|im_start|>":
        value = 0.098 if first else -0.025
    elif token == "<|im_end|>":
        value = 0.036 if first else -0.011
    elif token == "<|endoftext|>":
        value = 0.122 if first else 0.011
    elif token in OPEN_BLOCKS:
        value = -0.030
    elif token in CLOSE_BLOCKS:
        value = 0.052
    elif token == "<tool_call>":
        value = 0.023
    elif token == "s":
        value = -0.06
        if previous.endswith("%"):
            value = -0.92
        elif acronym:
