        value = -0.08
        if long_word:
            value = -0.63 if previous.startswith(" ") else -0.32
        elif acronym:
            value = -0.30
    elif token == " s":
        value = -0.27 if long_word else -0.13
    elif token == "S":
        value = -0.25 if long_word else -0.05 if acronym else 0.02
    elif token == " S":
        value = -0.14 if long_word or acronym else -0.05
    elif token == "(S":
        value = -0.18 if long_word or acronym else -0.08
    elif token == "/s":
