programs.sol:
"""Detect boundaries introducing quoted strings, paths and addresses.

Opening quotes (especially escaped quotes), URL separators, and colons
receive positive values. Quotes closing a list item are weakly negative.
A preceding number suppresses colons and slashes used in times or fractions.
Other tokens receive a near-zero baseline; word-specific fluctuations are
not modeled. Only the last token is remembered, resetting at each document.
"""

READS = ()


def quote_value(s):
    # Infer quote roles only for tokens made entirely of punctuation.
    if any(c.isalnum() for c in s):
        return None
    single = "'" in s and '"' not in s
    q = "'" if single else '"'
    if q not in s:
        return None
    escaped = '\\' + q in s
    clean = s.replace('\\' + q, q)
    before, after = clean.split(q, 1)
    if q in after:
        return 0.72 if ':' in after else 0.25
    if after.startswith(':'):
        return 0.79 if escaped else (0.13 if single else 0.26)
    if after.startswith(','):
        return 0.40 if escaped else (-0.15 if single else -0.11)
    if after.startswith(']'):
        return -0.22
    if after.startswith(')'):
        return 0.26 if escaped else (-0.07 if single else 0.01)
    if after.startswith('\\'):
        return 0.35 if not single else 0.0
    if after and not after.startswith(('/', '%', '_')):
        return 0.0
    if before.isspace():
        return 1.65 if escaped else (0.82 if single else 0.65)
    lead = before.strip()
    if lead.endswith('='):
        return 1.78 if escaped else 0.92
    if lead.endswith('('):
        if escaped:
            return 1.42
        return 0.39 if before.startswith(' ') else (0.47 if single else 0.61)
    if lead.endswith(('[', '{')):
        return 1.36 if escaped else 0.37
    if lead.endswith(':'):
        return 1.64 if escaped else 0.63
    if lead.endswith(','):
        return 0.6 if escaped else 0.10
    if not before:
        return (0.37 if single else 1.16) if escaped else 0.05
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    numeric = previous.strip().isdigit()
    value = quote_value(s)
    if value is not None:
        # Whitespace-separated opening quotes depend on the left boundary.
        if s in (' "', " '"):
            end = previous.rstrip()[-1:] if previous else ''
            if numeric:
                value = 0.35
            elif end == '=':
                value = 1.08 + 0.10 * ("'" in s)
            elif end and end in '.!?':
                value = 0.06 + 0.28 * ("'" in s)
            elif end and end in ',;:':
                value += 0.07
            elif (previous and not previous.startswith(' ')
                  and not previous.isspace()):
                value -= 0.15
        elif s in ('"', "'") and previous.isspace():
            value = 0.55
        elif (s == '\\"'
              and previous.rstrip().endswith(('(', '[', '{', '='))):
            value = 1.75
    elif s == '://':
        value = (0.66 if numeric
                 else 1.32 if previous.startswith(' ') else 1.61)
    elif s == ':':
        value = 0.08 if numeric else 0.32
    elif s == '/':
        value = 0.02 if numeric else 0.33
    elif s == ' /':
        value = 0.15 if numeric else 0.65
    elif s.strip() in ('“', '‘', '„') and s.startswith(' '):
        value = 0.33
    elif s in ('.com', '.org', '.net', '.edu', '.gov', '.io'):
        value = 0.65
        if previous.strip().lstrip('@').lower() in ('example', 'domain'):
            value = 2.1
        elif previous.strip().lower() == 'github' or previous.startswith(' '):
            value = 0.20
    elif s.strip().lower() in ('http', 'https', 'localhost'):
        value = 0.55
    elif s.strip().lower() == 'path':
        value = 0.33
    elif s == ':\\':
        value = 0.28
    elif s == '?:':
        value = 0.88
    elif s == '\\':
        value = 0.07
    else:
        value = -0.004
    return (doc, s), float(value)

programs.haiku:
"""Opening quotes, colons and URL separators in code (rule-based).

Component layers.0.mlp.down_proj:5068 fires on the punctuation that opens a
string literal, a URL or a label. Its strength depends on whether the text
just before looks like code (strong) or prose (weak):

- "://" (URLs) and escaped quotes \\" (strings inside JSON/tool calls): strongest.
- An opening quote (' "', " '", '="', '("', ...) : 0.4 in prose up to 0.9 in code.
- A colon after a word (labels, keys): 0.1 in prose up to 0.4 in code;
  a colon after a digit (times, dates) stays near 0.
- ".com"/".org" and "/" (domains and paths): moderate.
Everything else is 0.
"""

READS = ()

CODE_CHARS = set("=(){}[];<>\\_$#/:,|+*")
QUOTES = ('"', "'", "“", "\\\"")
OPENERS = ("=", "(", "[", "{", ":", ",")


def codiness(text):
    """Share of code-like characters in the text just before the token, in 0..1."""
    return min(1.0, 5 * sum(c in CODE_CHARS for c in text) / max(1, len(text)))


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    before = "".join(prefix.token_strings[-41:-1])
    code = codiness(before)
    s = tok.strip()
    if "://" in tok:
        value = 1.5
    elif "\\\"" in tok:
        value = 1.2
    elif s.endswith(QUOTES):
        if tok.startswith(" ") or s.startswith(OPENERS):
            value = 0.4 + 0.5 * code  # opening quote: strong in code, weaker in prose
        else:
            value = 0.1
    elif s == ":" and "\n" not in tok:
        value = 0.05 if prev[-1:].isdigit() else 0.1 + 0.3 * code
    elif s in (".com", ".org"):
        value = 0.7
    elif s == "/":
        value = 0.3
    else:
        value = 0.0
    return carry, value

programs.luna:
"""A sparse text-only estimate based on visible punctuation boundaries.

The rules add small cues for quoted text, labels, paths, and email-like
handles, then shrink those cues back toward the near-zero baseline.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = 0.007

    # Opening double quotes and escaped quotes often mark a string value.
    if '"' in token:
        quote = token.find('"')
        before = token[quote - 1] if quote else " "
        if before.isspace() or before in "([{=:,\\":
            value += 0.72

    # Typographic opening quotes have their own one-character tokens.
    if "‘" in token or "“" in token:
        value += 0.45

    # Single quotes count when they stand at a delimiter, not in contractions.
    if "'" in token:
        quote = token.find("'")
        before = token[quote - 1] if quote else " "
        if before.isspace() or before in "([{=:,":
            value += 0.58

    # Colons mark labels and structured fields; a slash can open a path or URL.
    if ":" in token:
        value += 0.22
    if "://" in token:
        value += 0.65
    elif "/" in token and token[:1].isspace():
        value += 0.42

    # Continue a path extension or an email domain from the previous token.
    if len(prefix.token_strings) > 1:
        previous = prefix.token_strings[-2]
        same_document = prefix.document_ids[-2] == prefix.document_ids[-1]
        if same_document and token.lstrip().startswith("."):
            if "@" in previous:
                value += 0.65
            elif "/" in previous:
                value += 0.38

    # Email-like handles are another common boundary in these snippets.
    if "@" in token:
        value += 0.65

    value = 0.007 + 0.5 * (value - 0.007)
    return carry, float(value)

programs.sol:
"""Sparse lexical cues for describing the structure and representation of data.

Schemas give the largest negative response, particularly after JSON. Types,
serialization, validation and table structure give weaker responses. Leading
spaces, case and identifier separators adjust a few common nouns. A carried
alphabetic ending recognizes split names; it resets at document boundaries.
"""
import re
READS = ()

# Typical strengths for vocabulary about data descriptions and their tools.
LEXICONS = (
    (-3.2, 'serde serialversionuid apimodelproperty'),
    (-2.7, 'protobuf'),
    (-2.3, 'isinstance nullable sqlalchemy objectmapper gson'),
    (-2.0, 'deserialize serializer serialization graphql proptypes pydantic'),
    (-1.7, 'serialize marshal unmarshal rdf swagger'),
    (-1.3, 'enum enums reshape proto joi primarykey fieldname getfield keyset '
           'parquet kafka typeerror'),
    (-1.1, 'struct validate validator typing typescript pandas validation'),
    (-0.8, 'type format fmt parser yaml typedef typename typeof typed '
           'instanceof sizeof'),
    (-0.7, 'json dataframe datetime syntax vocabulary'),
    (-0.6, 'api apis metadata signature timestamp encoder decoder sql protocol sdk'),
    (-0.5, 'df pd np numpy dict converter adapter'),
    (-0.4, 'xml attribute attributes entity entities parse interface object'),
    (-0.3, 'class definition structure structures'),
)
WORDS = {w: v for v, words in LEXICONS for w in words.split()}
SERIALIZATION_METHODS = {'dumps', 'loads', 'tojson', 'fromjson'}
NOUNS = {'field', 'fields', 'column', 'columns', 'model'}


def clean(token):
    return token.strip().strip('._-/\\()[]:,')


def response(token, previous):
    raw, prev = clean(token), clean(previous).lower()
    word = raw.lower()
    spaced = token.startswith(' ')
    member = token.startswith(('.', '_', '/'))
    value = WORDS.get(word, 0.0)
    if word.endswith(('schema', 'schemas')):
        return -8.5 if prev == 'json' else (-6.0 if member else -5.2)
    if word in SERIALIZATION_METHODS and member:
        return -2.7
    if word == 'schem':
        return -1.4
    if word == 'dtype':
        return -2.1 if spaced else -2.9
    if word in {'type', 'types'}:
        value = -0.8 if spaced else (-1.7 if word == 'types' else -0.9)
        if prev in {'data', 'primitive', 'incompatible', 'proto'}:
            value = -1.8
        elif prev in {'a', 'the', 'this', 'what', 'some', 'each', 'any'}:
            value = -0.4
        elif prev in {'import', 'export', 'return', 'input'}:
            value = -1.3
    if word in {'property', 'properties', 'shape', 'shapes'}:
        value = -0.18 if spaced else (-1.2 if 'shape' in word else -0.6)
    if word in NOUNS:
        value = -0.35 if spaced or not (member or raw[:1].isupper()) else -1.0
        if word == 'model' and spaced:
            value = -0.08
    if raw.endswith(('Type', 'Types')) and len(raw) > 5:
        value = -1.5
