        value = 1.27
    elif token.endswith('\\'):
        stem = token.rstrip('\\').strip()
        if not stem:
            slashes = len(word)
            value = -0.54 * (slashes - 1) if slashes > 1 else 0.0
            if slashes == 1 and token.startswith(' '):
                value = 0.15
        elif not any(c.isalnum() for c in stem):
            value = -1.4
            if stem[-1] in '{`':
                value = -2.25
            elif stem[-1] in '\"\';*':
                value = -2.0
            elif stem[-1] in '}+$^_':
                value = -1.0
            if len(stem) > 1 and not stem.startswith('\\'):
                if stem[-1] != ';':
                    value -= 0.45 * min(len(stem) - 1, 2)
            if token.startswith(' ') and stem[-1] in '{([}*|':
                value -= 0.4

    elif word in ('两', '兩', '几', '幾', '每'):
        value = -0.8  # two, a few, each
    elif word == '第二':
        value = -2.1  # second
    elif word == '第三':
        value = -1.6  # third
    elif '一' in word:
        if word == '一':
            value = -1.31
        elif word.endswith('一'):
            if word[-2] in '有这這那另每同下':
                value = -5.8  # have/this/that/another/each/same/next one
            elif word.endswith('第一'):
                value = -3.0  # first
            elif word.endswith('之一'):
                value = -2.85  # one of
            elif word in ('统一', '唯一', '单一', '一一', '逐一'):
                value = -0.6  # lexical compounds: unified, sole, single, etc.
            elif word[-2] in '二三四五六七八九十周':
                value = -1.5  # compound numbers or weekday names
            else:
                value = -3.6
        else:
