"""A lexical detector for development, authorship, and performing activities.

Creation verbs and creator roles are positive; articles and 'of' immediately
following them retain some signal; 'by/from' after activity words is negative.
Many code-like spellings are weaker. These are
word-class rules, not a parser. Selected non-English creation morphemes and
weak ordering/comparison cues are included. Product/label words receive a small
negative score. Unlisted words are zero unless a phrase rule applies.
"""

READS: tuple[str, ...] = ()


def verbs(roots, irregular=""):
    """Expand verb roots into common spellings; add supplied irregulars."""
    out = set(irregular.split())
    for r in roots.split():
        stem = r[:-1] if r.endswith("e") else r
        third_person = r + ("es" if r.endswith(("s", "sh", "ch", "x", "o")) else "s")
        out.update((r, third_person, stem + "ed", stem + "ing"))
    return out


DEVELOP = verbs("develop")
DESIGN = verbs("design")
INVENT = verbs("craft devise", "invented founded founding")
AUTHOR = verbs("write draft publish", "wrote written authored penned")
PRODUCE = verbs("produce manufacture prepare conduct")
BUILD = verbs("build construct assemble", "built")
CREATE = verbs("create compose generate")
ACT = verbs("perform operate host deliver introduce propose")
RUN = verbs("run", "running ran")
OWN = verbs("own edit", "editor editors")
MAKERS = set(
    (
        "author writer producer developer designer founder creator "
        "composer manufacturer"
    ).split()
)
MAKERS |= {w + "s" for w in MAKERS}
PROCESS = set(
    (
        "development production invention preparation construction "
        "creation composition formation"
    ).split()
)
LEADERS = set("director president ceo chairman chair leader".split())
ACTION = DEVELOP | DESIGN | INVENT | AUTHOR | PRODUCE | BUILD | CREATE | ACT | RUN

# Creation, development, manufacture, and writing morphemes.
ZH_STRONG = set("开发 研制 研发 制定 创办 打造 策划 撰写 创作".split())
ZH_MAKE = set("制作 制造 编写 谱写 构建 修建 建成 出品".split())
ZH_ACTION = set(
    (
        "建设 开展 设计 生产 出版 举办 运行 进行 实施 经营 完成 "
        "发展 建立 拍摄 成立 编辑 创造 制 製 编 編 造 写 寫 建 作 做 拍 立 成"
    ).split()
)


def lexical(w):
    if w == "development":
        return 0.7
    if w in {"designing", "authored"}:
        return 1.9
    if w in {"design", "written"}:
        return 1.0 if w == "design" else 0.55
    for words, value in (
        (DEVELOP, 1.65),
        (DESIGN, 1.3),
        (INVENT, 1.8),
        (AUTHOR, 0.85),
        (PRODUCE, 0.95),
        (BUILD, 0.5),
        (CREATE, 0.45),
        (ACT, 0.6),
        (RUN, 0.73),
        (OWN | MAKERS, 0.5),
        (PROCESS, 0.5),
        (ZH_STRONG, 2.5),
        (ZH_MAKE, 1.8),
        (ZH_ACTION, 0.85),
    ):
        if w in words:
            return value
    # Firstness and comparison are weaker secondary lexical cues.
    if w == "first":
        return 0.26
    if w in {"together", "behind"}:
        return 0.3
    if w in {"than", "out", "up", "do"}:
        return 0.18
    if w in {"doing", "done"}:
        return 0.4
    if w in {"custom", "customized", "development"}:
        return 0.7
    if w in {"的", "了", "出", "本", "開"}:
        return 0.1 if w == "的" else (0.25 if w == "了" else 0.4)
    # Russian creation/preparation; German, French, Spanish development.
    if w.startswith(("созд", "подготов", "entwick", "développ", "desarroll")):
        return 1.0
    if w in {
        "product",
        "products",
        "code",
        "version",
        "song",
        "story",
        "structure",
        "called",
    }:
        return -0.15
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = "" if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    w = raw.strip().lstrip("._-").lower()
    joined = False
    if not raw[:1].isspace() and w in {"ed", "ing", "s", "er", "ers", "ment"}:
        if lexical(previous + w):
            w = previous + w
            joined = True
    value = lexical(w)
    if value > 0.3 and w.isascii():
        if raw.startswith((".", "_")) and w not in OWN | RUN:
            value *= 0.35
        elif (
            not joined
            and not raw.startswith((".", "_"))
            and (raw.strip()[:1].isupper() or not raw[:1].isspace())
        ):
            value *= 0.6
    if w in {"create", "build"} and not raw[:1].isspace():
        value *= 0.25
    if w in {"write", "create", "build", "design"} and previous in {
        "to",
        "can",
        "will",
        "would",
        "you",
        "he",
        "we",
    }:
        value += 0.35
    if raw.startswith("-") and previous in {"co", "self"} and value > 0.3:
        value *= 2.2
    if w == "of":
        if previous in {"author", "writer", "producer"}:
            value = 1.8
        elif previous in MAKERS:
            value = 1.4
        elif previous in PROCESS | DESIGN | LEADERS:
            value = 0.9
    elif w in {"a", "an", "the"} and previous in ACTION:
        value = 0.45 if w == "the" else 0.65
        if w != "the" and previous in DEVELOP | DESIGN:
            value = 1.0
    elif w in {"by", "from"} and previous in ACTION:
        value = -0.18
    elif w == "out" and previous in {"carry", "carried", "carrying"}:
        value = 1.1
    elif w == "up" and previous in {"set", "setting", "sets"}:
        value = 0.95
    elif w == "forth" and previous == "set":
        value = 0.75
    return (doc, w), float(value)

"""A line-boundary detector, strongest for a bare single newline.

Longer lines and markup endings strengthen the response. Whitespace, numbers,
punctuation and function words or programming literals weaken it. Blank lines
respond less than single line breaks; document-initial newlines are treated
separately. Windows line endings, the user-role label and thinking tags have
separate responses. All remaining tokens predict zero.
"""
import math

READS = ()
FUNCTION_WORDS_AND_LITERALS = set('''the a an of to in on at for from by with as and or but
is are was were be been being it this that not if else true false None'''.split())


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, length, position = '', 0, 0
    else:
        _, previous, length, position = carry

    value = 0.0
    if token and not token.strip('\n'):
        single = len(token) == 1
        if position == 0:
            value = -0.153 if single else 0.07
        elif len(token) <= 2:
            value = 1.07 if single else 0.55
            value += 0.21 * min(length, 30) / 30
            value -= 0.07 / math.sqrt(position)
            word = previous.strip()
            if word.startswith('<') and word.endswith('>'):
                value += 0.24
            elif not word:
                value -= 0.68 if single else 0.36
            elif word.isdigit():
                value -= 0.17 if single else 0.04
            elif not any(c.isalnum() for c in word):
                value -= 0.40 if single else 0.26
            elif single and word in FUNCTION_WORDS_AND_LITERALS:
                value -= 0.15
        else:
            value = 0.35 * 0.55 ** (len(token) - 3)
    elif token == '\r':
        value = -0.17
    elif token in ('\r\n', '\r\n\r\n'):
        value = 0.64 if len(token) == 2 else 0.23
    elif token == 'user' and previous == '<|im_start|>':
        value = 0.73
    elif token == '<think>':
        value = -0.19
    elif token == '</think>':
        value = 0.27

    if '\n' in token:
        length = len(token.rsplit('\n', 1)[-1])
    else:
        length += len(token)
    return (doc, token, length, position + 1), float(value)

