READS = ()
VALUES = {
    'old': 3.5, 'new': 1.4, 'former': 3.2, 'existing': 1.8,
    'previous': 1.0, 'previously': 1.0, 'original': 0.75,
    'originally': 0.8, 'formerly': 2.7, 'newly': 1.4,
    'now': 0.65, 'once': 0.65, 'past': 0.45, 'latter': 0.7,
    'present': 0.45, 'older': 0.8, 'retired': 1.35,
    'deprecated': 1.3, 'obsolete': 1.5,
    # Chinese old (simplified/traditional), new, aged, original.
    '旧': 7.8, '舊': 6.3, '新': 1.5, '老': 1.0, '老旧': 2.9, '原': 0.9,
}
DEFINITE = {'the', 'my', 'your', 'his', 'her', 'our', 'their'}
AGE_UNITS = {'year': 1.0, 'years': 1.3, '-year': 1.4,
             'month': 1.9, 'months': 1.9, 'week': 2.0, 'weeks': 2.0,
             'day': 2.6, 'days': 2.6}


