    if word == 'old':
        value = 1.1 if raw == 'old' and prev[-1:].isalpha() else 2.8
        if spaced:
            value = 4.0 if before in DEFINITE else 3.5
            if raw == 'Old':
                value = 3.1
            value = AGE_UNITS.get(before, value)
        elif raw == '-old':
            value = 1.05
    elif word == 'new':
        value = 1.4 if spaced else 1.15
        if raw == 'New':
            value = 1.8 if spaced else 1.65
        elif spaced and before in DEFINITE:
            value = 1.65
        elif spaced and before in {'a', 'an', '='}:
            value = 1.23
    elif word == 'former':
        value = 3.2 if spaced or raw == 'Former' else 1.1
        if spaced and before == 'the':
            value = 3.6
        elif spaced and before == 'a':
            value = 2.9
