        "originally", "older", "veteran", "veterans", "vintage", "antique", "elderly",
        "陈", "陳", "老", "原", "以前", "过去", "曾经", "古", "стар", "преж", "废"}
NOW = {"now", "present", "presently", "once", "past", "今", "现在", "如今"}
FOREIGN_NEW = {"neue", "neuen", "neu", "nouveau", "nouvelle", "nuevo", "nueva", "yeni",
               "новый", "новые", "новых", "mới", "新しい", "새", "ใหม่", "nieuwe"}

VALUE = {}
for group, value in [(OLD, 3.0), (NEW, 1.4), (FOREIGN_NEW, 1.0), (PAST, 1.0), (NOW, 0.6)]:
    for word in group:
        VALUE[word] = value
VALUE["formerly"] = 2.6
VALUE["old"] = 2.6


def word_of(token):
    return re.sub(r"[^\w一-鿿]|_", "", token).lower()


AGE_UNITS = {"year", "years", "month", "months", "week", "weeks", "day", "days"}


