programs.sol:
"""Detect abrupt case or script changes between adjacent word fragments.

An unspaced capital letter or acronym following lowercase letters gives a
negative pulse. Lowercase fragments following an acronym give a smaller pulse.
Latin capitals after uncased Asian letters also receive a weaker pulse.
Longer title-case words do not count as acronym fragments.
Non-ASCII letters and escaped whitespace weaken the lower-to-upper pulse.
History resets when the document changes; all other positions predict zero.
"""
import unicodedata

READS: tuple[str, ...] = ()

JOINING_WORDS = {"to", "by", "of", "in", "on", "or", "no", "be"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    before_previous = carry[2] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    if token.isalpha() and previous:
        if previous[-1].islower() and token.isupper():
            n = len(token)
            value = -1.07 if n == 1 else -1.85 if n == 2 else -1.35
            if not token.isascii():
                value *= 0.50
            if not previous[-1].isascii():
                value *= 0.30
            if previous.endswith(("\\n", "\\t", "\\r")) or (
                previous in {"n", "t", "r"} and before_previous.endswith("\\")
            ):
                value = -0.20
        elif token.isascii() and token.isupper() and (
            previous[-1].isalpha()
            and not (previous[-1].isupper() or previous[-1].islower())
        ):
            kana = unicodedata.name(previous[-1], "").startswith(
                ("HIRAGANA", "KATAKANA")
            )
            value = -0.63 if kana and len(token) == 2 else (
                -0.30 if kana or len(token) == 2 else -0.10
            )
        elif token.isascii() and previous.isascii() and (
            previous[-1].isupper() and token.islower()
        ):
            capitals = 0
            for char in reversed(previous):
                if not char.isupper():
                    break
                capitals += 1
            if capitals >= 2:
                value = (-0.74 if len(token) == 1 else
                         -0.64 if len(token) == 2 else -0.50)
            elif len(token) == 1:
                value = -0.24
        elif token.isascii() and previous[-1].isalpha() and (
            token.istitle() and len(token) == 2
        ):
            if token.lower() not in JOINING_WORDS:
                value = -0.70 if token.endswith("s") else -0.25
    return (doc, token, previous), value

