"""Mark an uppercase abbreviation chunk beginning inside an unspaced name."""
READS = ()

def step(carry, prefix, upstream):
    if len(prefix.token_strings) < 2:
        return None, 0.0
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2]
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    if not token or not previous or token[0].isspace() or previous[-1].isspace():
        return None, 0.0
    left, right = previous[-1], token[0]
    if not (left.isascii() and right.isascii() and left.isalpha() and right.isalpha()):
        return None, 0.0
    if left.islower() and right.isupper():
        letters = [ch for ch in token if ch.isascii() and ch.isalpha()]
        if letters and all(ch.isupper() for ch in letters):
            return None, -1.2
    return None, 0.0

programs.sol:
"""Space-prefixed Western text interrupting Han-script writing.

Remember how much of the recent document uses Han characters, and whether
its last token did. A space-prefixed Latin token or punctuation mark gets a
negative response in that context. Short Latin fragments and opening curly
quotes respond most strongly; parentheses are intermediate. Other tokens
are mostly approximated by zero, with small quote and parenthesis offsets.
This captures the conspicuous script-boundary effect, not lexical variation.
"""
READS = ()


def has_han(text):
    return any('\u3400' <= char <= '\u9fff' for char in text)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, previous_han = 0.0, False
    else:
        _, recent, previous_han = carry

    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0
    if word in ('“', '‘', '”', '’'):
        value = 0.013

    if token.startswith(' ') and word:
        if word in ('“', '‘'):
            history_weight, previous_weight = 0.36, 0.25
        elif word in ('(', '（'):
            value = -0.005
            history_weight, previous_weight = 0.24, 0.15
        elif word.isascii() and word.isalpha():
            # Initials and short fragments interrupt Han text more sharply.
            history_weight = 0.045 + 0.18 / len(word)
            previous_weight = 0.09 + 0.09 / len(word)
        elif word.isascii() and not word.isalnum():
            history_weight, previous_weight = 0.12, 0.155
        else:
            history_weight, previous_weight = 0.0, 0.0
        value -= history_weight * recent + previous_weight * previous_han

    current_han = has_han(token)
    recent = 0.97 * recent + 0.03 * current_han
    return (doc, recent, current_han), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 5081.

What it does, in plain terms: this component is almost silent. Its activation is
usually within a few hundredths of zero, and its sign depends on the specific token
(rare tokens give larger swings, common ones are nearly flat), with no simple word
class that predicts the sign. The clearest large negative responses are in code-switched
text, where a Chinese passage is followed by an English token:

  * an opening quote or bracket written with a leading space (" “", " (", " `", " &", " $")
    right after Chinese or Japanese text: about -0.25;
  * an English word with a leading space right after Chinese or Japanese text: about -0.13.

Everywhere else the program predicts 0, the component's typical value. Predictions reset at
document boundaries. The program is a context rule, not a full model of the component: it
explains only a tiny share of its variance (see the explanation).
"""

READS = ()

OPENERS = {" “", " (", " `", " &", " $"}


def _is_cjk(s):
    return any(
        "぀" <= c <= "ヿ" or "一" <= c <= "鿿" or "가" <= c <= "힯"
        for c in s
    )


def _english_word(tok):
    return tok[:1] == " " and tok[1:].isascii() and tok[1:].isalpha()


def step(carry, prefix, upstream):
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    tok = prefix.token_strings[-1]
    if not _is_cjk(prefix.token_strings[-2]):
        return None, 0.0
    if tok in OPENERS:
        return None, -0.25
    if _english_word(tok):
        return None, -0.13
    return None, 0.0

