programs.sol:
"""Estimation language, with brief spillover into connecting words.

Guessing and estimating are the strongest cues; prediction and approximation
come next. Related judgments, measurements and uncertainty are weaker cues.
Word pieces are joined, but the ambiguous 'imat-' ending also responds in
unrelated words. Document boundaries reset the remembered word and response.
This deliberately omits small, idiosyncratic background activations.
"""
READS = ()

JUDGMENTS = set("""
assessment assessments judgment judgments judgement assumption assumptions
inference inferences diagnosis diagnoses diagnose diagnosed prognosis
conclusion conclusions conclude impression uncertainty uncertain unsure
unknown reconstruction measurement measurements diagnostic
""".split())
RELATED = set("""
assess assessed assume assumed assumes assuming hypothesis hypotheses
belief beliefs suspicion rough roughly crude advice recommendation
recommendations reasonable reasonably measuring measured accurate accurately
choice choices budget opinion recommend suggestions suggesting reasoning
bound bounds bet bets betting
""".split())


def lexical(word):
    if word in {"guess", "guesses", "guessing", "estimate"}:
        return 4.1
    if word.startswith("estimat"):
        if word[7:] not in {"e", "es", "ed", "ing", "ion", "ions", "or", "ors"}:
            return 0.0
        if "imator" in word:
            return 1.8
        return 2.6 if word.endswith("ed") else 3.3
    if word.startswith("predict"):
        if word[7:] not in {"", "ion", "ions", "ing", "ed", "ive", "able",
                            "or", "ors", "s"}:
            return 0.0
        return 1.6 if word.endswith(("ed", "ive", "able", "or", "ors")) else 2.9
    if word == "approx":
        return 2.1
    if word.startswith("approxim"):
        return 1.25 if word.endswith("ly") else 2.7
    if word.startswith("forecast") or word in {"infer", "inferred", "inferring"}:
        return 2.2
    if word in JUDGMENTS:
        return 1.2
    if word in RELATED:
        return 0.7
    if word in {"interval", "intervals", "confidence", "prior", "posterior"}:
        return 0.45
    # Chinese cues for estimating, guessing, judging and measuring.
    if word in {"预测", "預測", "估计", "估計", "估算"}:
        return 3.4
    if word in {"猜", "猜测", "猜測", "估"}:
        return 5.0
    if word in {"判断", "判斷", "断", "斷", "测", "測"}:
        return 2.0
    if word in {"评估", "評估", "测量", "測量", "推", "判", "≈"}:
        return 1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, strength = ("", 0.0) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip(" ._(/\\").lower()
    value = lexical(word)
    if token and token[0].islower() and word.isascii() and word.isalpha():
        joined = previous + word
        value = max(value * 0.85, lexical(joined))
        if word.startswith("imat"):
            value = 1.1
            if previous.endswith("est"):
                value = 4.5 if word == "imate" else 3.3
                if word.endswith(("or", "ors")):
                    value = 2.0
            if previous.endswith("approx"):
                value = 3.0 if word == "imate" else 2.6
        if word in {"ure", "ures", "ured"} and previous.endswith(("conject", "ject")):
            value = 3.0
        word = joined
    if word in {"conject", "estim"}:
        value = 1.0 if word == "conject" else 2.6
    if token.strip(" ._").lower() == "est":
        value = 1.1 if token.strip(" ._").istitle() else 0.2
    if word in {"of", "on", "about", "for", "to", "the", "a", "an", "that"}:
        rate = 0.8 if word in {"of", "about"} else 0.2
        if word in {"on", "for"}:
            rate = 0.5
        value += rate * strength
    if word == "about":
        value += 0.15
    return (doc, word[-40:], value), float(value)

"""Approximate the component's strongest signal: closing curly braces in code.

Predict nearly zero otherwise. Block endings on separate or indented lines
get large negative values; inline and combined punctuation get weaker ones.
Backslash-letter commands receive a near-zero value, avoiding many formula
braces. Keep only the previous token and 128 characters of the current line;
escaped newlines/tabs count as layout, even when split between tokens.
"""
import re

READS = ()


def brace_value(token, previous, line):
    head, brace, tail = token.partition('}')
    if not brace or '{' in head or any(c.isalnum() for c in head):
        return -0.001
    if re.search(r'\\[A-Za-z]+', line):
        return 0.02
    spaced = bool(head) and head.isspace()
    # Diff markers and comment slashes may precede indentation.
    at_start = not line.strip(' \t\r+-/')
    gap = previous.isspace() or previous.endswith('\\t')
    if '"' in head or "'" in head:
        return -0.39 if tail.startswith('}') else -0.27 if tail else -0.12
    if head.strip() and head.strip() not in (';', '//'):
        return -0.50 if ';' in head else -0.25

    # Estimate an ordinary brace's strength from code layout.
    if not previous:
        strength = 0.58 if not tail else 1.0
    elif at_start:
        strength = 0.8 if previous[-1:].isalnum() else 1.55 if not tail else 1.27
    elif gap:
        strength = 1.44 if not tail else 1.12
    elif ';' in line:
        strength = 1.05 if not tail else 0.65
    else:
        strength = 0.52 if spaced else 0.15 if not tail else 0.30

    if head.strip() == ';':
        strength = 1.1

    # Combined closing punctuation has a smaller response.
    if tail.startswith('}'):
        inline = spaced and not at_start and not gap
        strength = min(strength, 0.20 if inline else 0.55)
    elif tail.startswith(')'):
        inline = spaced and not at_start and not gap
        strength = min(strength, 0.31 if inline else 0.71)
    elif tail.startswith((',', ';')):
        strength = min(strength, 1.0 if '\n' in tail else 0.9)
    elif tail.startswith('\\'):
        strength = (1.12 if spaced else 0.85) if at_start or gap else 0.35
    elif tail.startswith(('else', 'while', 'catch', '//')):
        strength = 1.55 if at_start or gap else 0.70
    elif tail.startswith('`') and ';' in line:
        strength = 1.05
    elif tail and not tail[0].isspace():
        strength = min(strength, 0.65 if at_start else 0.30 if spaced else 0.14)
    elif '\r' in tail and tail.count('\n') == 1 and at_start:
        strength = 1.45
    elif tail.count('\n') > 1 and at_start:
        strength = 1.22
    return -strength


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, line = '', ''
    else:
        _, previous, line = carry
    token = prefix.token_strings[-1]
    value = brace_value(token, previous, line)
    line = (line + token).replace('\\n', '\n').replace('\\t', '\t')
    line = line.replace('\\r', '\r').rsplit('\n', 1)[-1][-128:]
    return (doc, token, line), float(value)

programs.luna:
"""Recognize words about something appearing, happening, or being available."""

READS = ()


def _classify(word):
    w = word.lower()
    if w.startswith("appear"):
        if w.startswith("appearance"):
            return -2.8
        return -6.0
    if w.startswith("apparent"):
        return -0.9
    if w.startswith("appara"):
        return -0.8
    if w.startswith("happen"):
        return -3.0
    if w.startswith("occur"):
        return -2.7
    if w.startswith("aris"):
        return -0.7
    if w.startswith("seem"):
        return -2.6
    if w.startswith("exist"):
        return -0.55
    if w.startswith("presenc"):
        return -0.7
    if w.startswith("availab"):
        return -0.7
    if w.startswith("visib"):
        return -1.05
    if w.startswith("invisib"):
        return -1.05
    if w.startswith("emerg"):
        return -0.55
    if (w.endswith(("出现", "出现了", "出现的", "现象"))):
        return -2.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        word = ""
    else:
        word = carry[1]

    completed = ""
    for ch in prefix.token_strings[-1]:
        if ch.isalnum():
            word += ch
        else:
            if word:
                completed = word
            word = ""

    return (doc, word), _classify(word or completed)

programs.sol:
"""A token-spelling approximation centered on sensory vocabulary.

Positive word families concern mouth/nose, taste/smell, hearing, breathing,
weather, food preparation, public officials, and public judgments. Chinese
sensory roots are checked too. SQL/null/linting and Android have separate
responses. Chat boundaries depend on document position. Other tokens use
small script-, capitalization-, and length-based baselines. This leaves much
of the component's idiosyncratic lexical variation unexplained.
"""
READS = ()

# Familiar stems permit inflections and compounds without a token table.
STEM_CLASSES = (
    (0.68, 'nose nostr mouth tongu throat palat nasal oral auditory olfact'),
    (0.46, 'eye eardrum cochlea pupil sensory blind deaf'),
    (0.79, 'smell tast flavor flavour scent aroma fragr perfume odor odour'),
    (0.62, 'hear heard listen voice vocal speech audience whisper loud'),
    (0.28, 'sound silent silence audio acoustic speaker microphone '
           'headphone earphone headset stereo radio'),
    (0.83, 'breath inhal exhal respir pulmonary cough lung snork pneumo'),
    (0.43, 'weather atmospher cloud breeze fog mist rain thunder lightning '
           'storm humid thermostat temperature fountain'),
    (0.91, 'oven cooker toaster dishwasher spoon teaspoon tablespoon '
           'culinary sandwich muffin'),
    (0.71, 'police sheriff governor mayor judge judicial attorney prosecut '
           'magistrate senator ambassador diplomat juror'),
    (0.68, 'search'),
    (0.33, 'question'),
    (0.65, 'opinion reputat prejudic unbiased impartial racis sexis '
           'discriminat'),
    (0.43, 'announc'),
)
STEM_CLASSES = tuple((v, tuple(s.split())) for v, s in STEM_CLASSES)

# Simplified and traditional Chinese sensory characters.
CHINESE_CLASSES = (
    (1.59, frozenset('鼻嘴唇舌喉嗅舔吞咽嚼吹喷噴喘咳哮嘘噓呕嘔嘟唾'
                     '喧嚣囂嘈哑啞嗡嗷嚎呱咕啼嘶吼喂哨噪啸嘯')),
    (0.87, frozenset('听聽耳眼瞳味臭吸呼喝肺胃腔')),
    (0.51, frozenset('闻聞香喊唱哼响響声聲音')),
    (0.85, frozenset('风風云雲雷雾霧浪海伞傘')),
    (0.50, frozenset('气氣')),  # Air/gas.
    (0.50, frozenset('脸臉颜顏颊頰腮颧顴视視眨瞪瞥瞅瞰瞎盲')),
)


def lexical(token):
    word = token.strip().lstrip('./_-(@').lower()
    if word == 'null':
        return 0.38 if token.strip() == 'NULL' else 0.66
    if word in ('sql', 'mysqli', 'postgresql', 'mysql', 'resultset'):
        return 0.94
    if word in ('eslint', 'tslint'):
        return 1.29
    if word.startswith(('lint', 'pylint')):
        return 0.51
    if word.startswith(('android', 'widget')):
        return -0.44
    if word in ('ear', 'ears', 'lips', 'senses'):
        return 0.46
    if word in ('wind', 'winds', 'windy'):
        return 0.43
    if word in ('pne', 'muff'):
        return 0.83 if word == 'pne' else 0.91
    if word.startswith('heart'):
        return background(token)  # "heart" is not a hearing word.
    for strength, stems in STEM_CLASSES:
        if word.startswith(stems):
            return strength
    for strength, roots in CHINESE_CLASSES:
        if any(char in roots for char in token):
            return strength
    return background(token)


def background(token):
    word = token.strip()
    if not any(char.isalpha() for char in word):
        return 0.07 if '\ufffd' in word else 0.001
    if any('\u4e00' <= char <= '\u9fff' for char in word):
        return 0.07
    if any('\uac00' <= char <= '\ud7a3' for char in word):
        return 0.06
    if word.isascii() and word.isalpha():
        if token.startswith(' ') and word.isupper() and 3 <= len(word) <= 4:
            return 0.10
        if token.startswith(' ') and word.istitle() and len(word) >= 5:
            return 0.09
        if len(word) >= 5:
            return 0.02
        return 0.001
    return 0.02


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    position = 0 if carry is None or carry[0] != doc else carry[1] + 1
    token = prefix.token_strings[-1]
    if token == '<|im_start|>':
        value = 0.426 if position == 0 else 1.006
    elif token == '<|im_end|>':
        value = -0.34 + 0.35 / (1.0 + position / 15.0)
    elif token == '<|endoftext|>':
        value = 0.065 + 0.38 / (1.0 + position / 5.0)
    elif token in ('<think>', '</think>'):
        value = 0.35 if token == '<think>' else 0.41
    else:
        value = lexical(token)
    return (doc, position), float(value)

programs.haiku:
"""Layer-0 MLP unit 5086: a lexical detector for rarer words and chat-turn tokens.

What it does, in plain terms: the unit reads only the current token. It is strongly
positive on the chat-turn token <|im_start|>, negative on <|im_end|>, mildly positive on
the think tags, and mildly positive on rarer words: proper nouns (capitalised, longer
ones more), and text written in non-Latin scripts (CJK, Hangul, Thai, Arabic, ...).
Common English function words, punctuation, digits and whitespace stay near zero.
Each value is the average activation of its group, so the program explains only the
group-level mean; the large spikes on individual rare words are not predicted.
"""

READS = ()

SPECIAL = {"<|im_start|>": 0.93, "<|im_end|>": -0.30, "<think>": 0.38, "</think>": 0.38}

FUNCTION_WORDS = set(
    "the a an of and or to in on at by for with from as is are was were be been "
    "being it its this that these those i you he she we they me him her us them my "
    "your his our their not no but if so than then there here what which who when "
    "where why how all any some can will would should could may might must do does "
    "did have has had about into over up out just also s t".split()
)

# typical activation by writing system, for words that are not plain ASCII
SCRIPT_VALUE = {"CJK": 0.07, "THAI": 0.12, "HANGUL": 0.06, "ARABIC": 0.045, "HIRAGANA": 0.04,
                "LATIN": 0.03, "CYRILLIC": 0.02}


def script_of(word):
    for ch in word:
        if ch.isalpha():
            if ch.isascii():
                return "ASCII"
            if "一" <= ch <= "鿿":
                return "CJK"
            if "฀" <= ch <= "๿":
                return "THAI"
            if "가" <= ch <= "힯":
                return "HANGUL"
            if "؀" <= ch <= "ۿ":
                return "ARABIC"
            if "぀" <= ch <= "ヿ":
                return "HIRAGANA"
            if "Ѐ" <= ch <= "ӿ":
                return "CYRILLIC"
            return "LATIN"
    return "NONE"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in SPECIAL:
        return carry, SPECIAL[token]
    word = token.strip()
    if "�" in word:
        return carry, 0.09
    if not word or word.lower() in FUNCTION_WORDS or not word.isalnum() or word.isdigit():
        return carry, 0.0
    script = script_of(word)
    if script != "ASCII":
        return carry, SCRIPT_VALUE.get(script, 0.03)
    if token.startswith(" ") and word[:1].isupper():
        return carry, 0.09 if len(word) >= 5 else 0.05
    if token.startswith(" ") and word.isalpha():
        return carry, 0.016
    return carry, 0.007

programs.sol:
"""Detect detached whitespace and text attached to symbolic boundaries.

Single-space tokens fire after line ends, numbers, fragments and content
words, but much less after function words, month names and operators.
Unspaced text after # or a code-comment opener fires more strongly.
These are approximate class averages, using only the previous token.
"""
READS = ()
MONTHS = set(('january february march april may june july august september '
              'october november december jan feb mar apr jun jul aug sep '
              'sept oct nov dec').split())
FUNCTION_WORDS = set((
    'an the and or but of in on at to for from with by as is are was were '
    'be been being am do does did have has had that this these those it its '
    'their his her our your my they we you he she not no if then than into '
    'over under between since after before until during per de la le el '
    'who what which where when how there here because while so through '
    'within without can could should would will might must all each every '
    'any some just also using including').split())
APPROXIMATIONS = set(('about approximately around nearly roughly circa '
                      'exactly least only more less most almost').split())


def space_value(previous):
    p = previous.strip()
    if previous.endswith('\n'):
        return 0.83
    if not p:
        return 0.0 if previous else -0.11
    if p.endswith(('#', '//')):
        return -0.32
    if p[-1].isdigit():
        return 0.54
    if p.lower() in MONTHS:
        return -0.20
    if p.lower() in APPROXIMATIONS:
        return -0.24
    if p.lower() in FUNCTION_WORDS:
        return 0.0 if previous.startswith(' ') else 0.30
    if p == 'a' and previous.startswith(' '):
        return 0.27
    if p in ('=', '==', '===', '!=', '<=', '>=', '=>', ':=', '+=', '-='):
        return -0.15
    if p[-1] in '.!?)\"\'’”]}':
        return 0.56
    if p[-1] in '。！？':
        return 0.95
    if not any(c.isalnum() for c in p):
        return 0.0 if previous.startswith(' ') else 0.12
    if len(p) == 1 and p.isalpha():
        return 0.64
    if not previous.startswith(' '):
        return 0.53
    if p.isupper():
        return 0.69
    return 0.47 if p.istitle() else 0.35


def value(previous, s):
    if s == ' ':
        return space_value(previous)
    if s.isspace():
        if s.startswith(' ') and '\n' in s:
            spaces = len(s) - len(s.lstrip(' '))
            return 0.62 if spaces == 1 else 0.35 if spaces == 2 else 0.0
        if s == '\xa0':
            return 0.34
        return -0.58 if previous.endswith(('#', '//', '/*')) else 0.0
    if s and s[0].isalnum() and previous == previous.rstrip():
        if previous.endswith('#'):
            return 0.15 if previous.endswith('&#') else 1.15
        if previous.endswith('/*') or (
                previous.endswith('//') and ':' not in previous):
            return 1.11  # Not URL ://.
        if previous.endswith('*'):
            return 0.08 if previous.endswith('**') else 0.45
        if previous.endswith(('&', '%', '|')):
            return 0.47
        if previous.endswith(('--', '...', '…', '!')):
            return 0.36
        if previous.endswith('{') and previous != '{':
            return 0.0 if previous.endswith(('_{', '^{', '\\{')) else 0.25
    if previous.endswith(('#', '//', '/*')) and ':' not in previous:
        return -0.17 if s.startswith(' ') else 0.18
    if s == ' �':
        return 0.22
    return -0.12 if s == '\\' else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    return (doc, s), float(value(previous, s))

programs.luna:
"""Predict the component's strongest readable cues: ordinary and paragraph
spacing, plus a word or number immediately following a single hash marker.
A doubled hash (a common heading marker) is deliberately not treated as a tag.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ""

    after_hash = (
        history.endswith("#")
        and not history.endswith("##")
        and token.isascii()
        and token.isalnum()
    )
    if after_hash and token.isalpha():
        value = 1.20
    elif after_hash and token.isdigit():
        value = 0.75
    elif after_hash:
        value = 0.85
    elif token == " ":
        value = 0.19
    elif token == "\xa0":
        value = 0.38
    elif token.isspace() and token.startswith(" ") and "\n" in token:
        value = 0.66
    else:
        value = 0.0

    return (doc, (history + token)[-64:]), value

programs.sol:
"""Negative pulses for basic knowledge and introductory subject matter.

The rules recognize educational vocabulary, strengthen it after foundational
or technical modifiers, and continue the signal onto 'to'/'of' in phrases
such as 'Introduction to' and 'fundamentals of'. Other tokens stay near zero.
A short text tail joins word fragments and resets at document boundaries.
This is partial: smaller, token-specific offsets are not modeled.
"""
import re

READS = ()
LEVELS = (
    ({'basics', 'fundamentals'}, -0.9),
    ({'concepts', 'notions', 'introductory', 'preliminaries',
      '知识', '掌握', '基礎', '入门'}, -0.5),
    ({'topics', 'skills', 'introduction', 'intro', '技能', '基础'}, -0.3),
    ({'basic', 'advanced', 'fundamental', 'principles', 'knowledge',
      'techniques', 'terminology', '基本', '概念', '知識'}, -0.2),
)
FOUNDATIONAL = {'basic', 'fundamental', 'essential', 'core', 'key'}
TECHNICAL = {'mathematical', 'theoretical', 'algebraic', 'programming',
             'technical', 'professional', 'general', 'prior', 'background'}
NOUNS = {'concepts', 'notions', 'topics', 'skills', 'knowledge', 'theory',
         'understanding'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    text = (before + token)[-64:]
    words = re.findall(r'[A-Za-z]+', text)
    word = words[-1].lower() if words and token[-1:].isascii() else token.strip()
    if not token[-1:].isalpha():
        word = ''
    prev = words[-2].lower() if len(words) > 1 else ''
    value = -0.001
    for group, level in LEVELS:
        if word in group:
            value = level
            break
    if word in NOUNS:
        if prev in FOUNDATIONAL:
            value -= 0.75
        elif prev in TECHNICAL:
            value -= 0.35
    if word == 'to' and prev in {'introduction', 'intro'}:
        value = -1.2
    elif word == 'of' and prev in {'basics', 'fundamentals'}:
        value = -1.3
    elif word == 'of' and prev in {
        'concepts', 'knowledge', 'skills', 'principles'
    }:
        value = -0.3
    if word in {'知识', '技能', '概念'} and before.endswith(
        ('基本', '核心', '理论')
    ):
        value -= 0.6
    return (doc, text), float(value)

"""Approximate a negative detector for OC-like spelling pieces.

Short 'oc' and 'doc' tokens get the largest negative responses. Named
word families for documents, location/allocation, focus, society,
occupation and topics get smaller negative responses. This is primarily
an approximation of spelling and token shape, not sentence meaning.
Whitespace, capitalization and attached punctuation alter the strength.
A preceding token is used only for slash-prefixed documents and for a lone
C inside a word or acronym. Other tokens are approximately zero.
"""

READS = ()

# Recognizable word families, not a list of token IDs.
FAMILIES = (
    ('docum', 0.65), ('locat', 1.05), ('relocat', 1.05),
    ('ocation', 1.2), ('locals', 1.2), ('locus', 1.4),
    ('alloc', 1.4), ('dealloc', 1.4), ('societ', 1.15),
    ('social', 0.18), ('soci', 1.4), ('occup', 1.0),
    ('occurrenc', 1.0), ('topic', 1.1),
)


def response(token, previous=''):
    spaced = token[:1].isspace()
    text = token.strip()
    bare = text.lstrip('._/-(\\')
    mark = text[:len(text) - len(bare)]
    word = bare.lower()
    capital = bare[:1].isupper()

    if word in ('doc', 'docs'):
        plural = word.endswith('s')
        if mark == '/':
            return -1.3 if plural else -6.2
        if mark in ('_', '(', '.'):
            return -1.8 if plural else -3.5
        if spaced:
            if plural:
                return -3.2 if capital else -2.05
            return -4.2 if capital else -3.75
        if plural:
            return -3.3
        if capital:
            return -4.3
        return -6.2 if previous.endswith('/') else -4.9
    if word in ('oc', 'ocs'):
        if mark:
            strength = 3.4
        elif spaced:
            strength = 2.8
        else:
            strength = 4.2 if capital else 5.2
        return -strength * (0.73 if word.endswith('s') else 1.0)
    root = word[:-1] if word.endswith('ocs') else word
    if root.endswith('oc'):
        strength = 3.0 if len(root) <= 3 else 1.0
        if root.endswith(('proc', 'roc', 'inoc', 'monoc', 'malloc')):
            strength = 1.6
        if root == 'alloc':
            strength = 3.3
        if root == 'iloc':
            strength = 2.5
        if root == 'loc' and mark == '.':
            strength = 2.0
        return -strength * (0.75 if root != word else 1.0)

    # OC derivatives, including the broader idea of focus/priority.
    if word.startswith('focus'):
        if word.endswith('ed'):
            return -1.6
        return -2.8 if word == 'focus' else -2.4
    if word.startswith(('focal', 'ocus', 'ocusing')):
        return -1.8 if word.startswith('focal') else -2.3
    if word.startswith('concentr'):
        if word.startswith('concentration'):
            return -0.38
        return -0.65 if word.endswith('ed') else -1.4
    if word.startswith('priorit'):
        return -1.15 if word in ('priorit', 'priorities') else -0.7
    if word in ('emphasis', 'devoted'):
        return -0.85
    if word == 'located':
        return -0.75
    if bare == 'Society':
        return -2.0
    if word.startswith(('documentar', 'documentation')):
        return -0.9
    for stem, strength in FAMILIES:
        if word.startswith(stem):
            return -strength

    if word.startswith(('occur', 'oct', 'occasion')):
        return -0.25 if len(word) < 7 else -0.05
    if word.startswith('ocean'):
