    if word.startswith('oc'):
        if word in ('occ', 'oci', 'oca', 'oco'):
            return -2.5 if word == 'occ' else -1.8
        return -0.4 if word.startswith(('ock', 'och')) else -0.9

    # Nearby spellings and short c fragments.
    if word in ('ок', 'ốc', 'ц', 'оч'):
        if word == 'ốc':
            return -1.9
        return -1.0 if word == 'ок' else -0.5
    if not spaced and word in ('ok', 'ox', 'oz'):
        return -0.4
    if text in ('c', 'C') and not spaced:
        last = previous[-1:]
        if last.isalpha():
            return -0.7 if text == 'C' and last.isupper() else -0.35
        if last.isdigit():
            return -0.15
        return -0.08 if text == 'C' else 0.0
    if word == 'c':
        return -0.3 if mark in ('.', '-') else 0.0
    if word.endswith(('ic', 'ac', 'nc', 'cc')):
        return 0.0
    if len(word) == 2 and word.endswith('c'):
        if word[-2] in 'eu':
            return -0.3
        return -0.45 if not spaced or bare.isupper() else -0.15
    if len(word) == 3 and word.endswith(('ec', 'uc')):
        return -0.35
    return 0.0


def step(carry, prefix, upstream):
    previous = ''
    if len(prefix.token_strings) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]
    return None, float(response(prefix.token_strings[-1], previous))

"""A local demonstrative-description signal.

An approximate local phrase signal, not a full activation reconstruction.

The largest response marks linking verbs in 'this is', 'these are', and
'here is'. It fades quickly across intervening tokens. A smaller response
continues onto articles in 'this is a'. Research-document, time, and some
situational words following 'this' instead get negative values. Capitalized
demonstratives retain more influence
through a noun phrase; document-initial 'this' has a larger predicate signal.
Small additional rules cover code-member access, 'External links', and Chinese
'这是' ('this is').
"""
READS = ()

# Values for an immediately preceding 'this' (or 'these' with plural verbs).
LINKING = {
    'is': 3.73, 'was': 2.79, 'are': 2.3,
    'were': 1.68, 'be': 2.65, "'s": 2.74,
    '’s': 2.73, 'isn': 2.19, 'wasn': 1.77,
    'seems': 1.34,
}
MODALS = set('will would can could may might should must'.split())
RESEARCH = {'study', 'paper'}
TIME = {'year', 'day'}
LEGAL_GEOGRAPHIC = {'country', 'court'}
WRITING = {'book', 'review', 'invention'}
MODIFIERS = {'way', 'new', 'particular', 'latter', 'following'}
DISCOURSE_OBJECTS = {
    'question', 'problem', 'answer', 'solution', 'message',
    'product', 'preview',
}


def auxiliary_value(word):
    if word in MODALS or word == 'does':
        return 1.1
    if word == 'has':
        return 1.4
    return .65 if word in {'have', 'do'} else 0.0


def description_value(word):
    if word in RESEARCH or word in LEGAL_GEOGRAPHIC:
        return -1.7
    if word in TIME or word in MODIFIERS:
        return -1.1
    if word in WRITING:
        return -.85
    if word in DISCOURSE_OBJECTS or word in {'a', 'an'}:
        return 1.0
    return 1.8 if word in {'one', 'information', 'content'} else 0.0


DEICTIC = {
    'this': 1.0, 'these': 1.0, 'here': .63,
    'following': .75, 'below': .75,
    'that': .10, 'those': .08, 'which': .15,
    'present': .4,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0.0, 0.0, 0.0, .3, '', 0.0)
    _, age, linking, auxiliary, nominal, decay, previous, prev_value = carry
    age += 1
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    anchor_word = word.lstrip('"“>\'')
    spaced = token.startswith(' ')
    value = 0.0
    if spaced or word in {"'s", '’s'}:
        value = LINKING.get(word, 0.0) * linking
        value += auxiliary_value(word) * auxiliary
        value += description_value(word) * nominal
        if word == 'is' and previous == 'here' and linking < .7:
            value *= .7
        if word in {"'s", '’s'} and previous == 'that':
            value = .43 + 2.0 * linking
        if word in {'a', 'an', 'the', 'one', 'some'}:
            if previous in LINKING:
                value += .21 * max(0.0, prev_value)
    # Member access uses 'this' as a code-object reference rather than prose.
    if previous == 'this' and token.startswith('.'):
        member = token[1:]
        if member and member[0].isalpha():
            value = -.45
    if word == 'links' and previous == 'external':
        value = .5
    # Chinese demonstrative + copula, sometimes fused in a single token.
    if token == '这是':
        value = 1.4
    # The immediately preceding demonstrative matters much more than a distant one.
    retention = decay
    if word in MODALS:
        retention = .65 if word in {'may', 'might'} else .45
    linking *= retention
    auxiliary *= .25
    nominal *= .22
    if anchor_word in DEICTIC:
        strength = DEICTIC[anchor_word]
        # Sentence-initial capitalization gives these phrases a stronger response.
        letters = token.lstrip(' \t\n\"“>\'')
        capitalized = letters[:1].isupper()
        if capitalized:
            boost = {'that': 3.0, 'which': 1.9}.get(anchor_word, 1.22)
            strength *= boost
            if not token.startswith(' '):
                strength *= 1.12
        linking = auxiliary = strength
        decay = .4 if capitalized else .26
        if anchor_word in {'this', 'these'}:
            if age <= 64:
                linking *= 1.22 if age <= 16 else 1.07
        nominal = 0.0
        if anchor_word in {'this', 'following', 'present'}:
            nominal = strength
    if any(ch in token for ch in '.;!?\n'):
        linking = auxiliary = nominal = 0.0
    carry = (doc, age, linking, auxiliary, nominal, decay, word, value)
    return carry, float(value)

programs.haiku:
"""Copula after a demonstrative subject ('This is', 'Here's', 'These are'), and the word that
starts the predicate after it ('This is a', 'This may be'); research/time nouns after 'this'
('this study', 'this year') are negative."""
DEICTIC = {"this": 1.0, "these": 0.9, "here": 0.6, "following": 0.7, "below": 0.7, "That": 0.3}
COPULA = {"is": 4.2, "was": 3.2, "are": 2.7, "'s": 2.0, "will": 1.1, "may": 1.5,
          "might": 1.1, "can": 0.9, "would": 0.8, "has": 1.5, "isn": 2.3, "be": 1.0}
PREDICATE_START = {"a": 1.0, "an": 1.0, "be": 1.0, "one": 0.9, "some": 0.9, "the": 0.6}
NOUNS_AFTER_THIS = {"study": -1.8, "paper": -1.8, "way": -1.4, "year": -1.0, "book": -0.8,
                    "article": -0.8, "invention": -0.9, "century": -1.0, "country": -1.7,
                    "court": -1.7, "new": -1.2, "review": -1.0}
READS = ()

def _word(prefix, back):
    """The stripped token `back` positions before the current one (raw, lowercased), or None
    if it is in another document."""
    i = len(prefix.token_strings) - 1 - back
    if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
        return None, ""
    raw = prefix.token_strings[i].strip()
    return raw, raw.lower()

def step(carry, prefix, upstream):
    _, cur = _word(prefix, 0)
    raw_prev, prev = _word(prefix, 1)
    _, prev2 = _word(prefix, 2)
    value = 0.0
    if raw_prev is not None:
        if prev in DEICTIC and cur in COPULA:
            value = DEICTIC[raw_prev if raw_prev == "That" else prev] * COPULA[cur]
        elif prev in DEICTIC and cur in NOUNS_AFTER_THIS:
            value = NOUNS_AFTER_THIS[cur]
        elif cur == "is" and prev in ("which", "that"):
            value = 0.5
        elif prev in COPULA and prev2 in DEICTIC and cur in PREDICATE_START:
            value = PREDICATE_START[cur]
    return carry, value

programs.luna:
"""A small surface sketch of a sparse word-and-context response.

It assigns a modest positive value to selected verbs when a nearby pronoun or
demonstrative occurs in the preceding four tokens, and a modest negative value
to three recurring nouns. This is a lexical cue, not a parse.
"""
READS = ()

PREDICATES = {"is", "are", "was", "were", "will", "could", "does", "has", "shows", "'s"}
SUBJECT_WORDS = {"this", "these", "that", "those", "you", "which", "it"}
NEGATIVE_NOUNS = {"study": -1.0, "year": -0.7, "century": -0.5}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if token in NEGATIVE_NOUNS:
        return None, float(0.5 * NEGATIVE_NOUNS[token])
    if token not in PREDICATES:
        return None, 0.0

    position = prefix.position
    start = max(0, position - 4)
    nearby = any(
        prefix.document_ids[i] == prefix.document_ids[position]
        and prefix.token_strings[i].strip().lower() in SUBJECT_WORDS
        for i in range(start, position)
    )
    if not nearby:
        return None, 0.0
    return None, 0.7 if token == "is" else 0.4

