"""A spelling-sensitive money detector, with an opposite response to T fragments.

Money and a few translations fire strongly; currencies and financial vocabulary
fire more weakly. The suffix 'oney' fires even in unrelated names. T, short
capitalized T fragments, and punctuation-attached T are negative. Bare
T is especially negative at document start, but weaker after another capital.
Money matching ignores case, whitespace and leading hyphens, with a separate
rate for bare lowercase 'money'. Other tokens are zero; no topic is inferred.
"""
READS = ()

MONEY = {'dinero', 'dinheiro', 'деньги', 'денег', '錢', 'お金', 'お金を',
         '有钱', '的钱', '金钱', '花钱', '省钱'}
OTHER_MONEY_WORDS = {'dollars', 'geld', '人民币', '赚钱'}
CHINESE_FINANCE = {'钱包', '货币', '资金', '資金', '多少钱'}
CASH = {'cash', 'monetary', 'penny', 'pennies', 'cents', 'bucks', 'dollar',
        'tiền', 'usd', '富裕'}
FUNDS = {'funds', 'currency', 'currencies', 'wallet'}
FINANCE = {'financial', 'finance', 'funding', 'revenue', 'coin', 'coins', '金融'}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token, word = raw.strip(), raw.strip().lower().lstrip('-')
    start = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    prev = '' if start else prefix.token_strings[-2].rstrip()
    if word == 'money':
        value = 4.0 if raw == 'money' else 5.6
    elif token == '钱':
        value = 5.0
    elif word in MONEY:
        value = 3.4
    elif word == 'oney':
        value = 2.5
    elif word in OTHER_MONEY_WORDS:
        value = 2.0
    elif word in CHINESE_FINANCE:
        value = 1.4
    elif word in CASH:
        value = 0.9
    elif word in FUNDS:
        value = 0.6
    elif word in FINANCE:
        value = 0.35
    elif token == 'T':
        if start:
            value = -3.8
        elif raw.startswith(' '):
            value = -1.1
        elif prev and prev[-1].isupper():
            value = -0.65
        else:
            value = -1.44
    elif token == 'Te':
        value = -1.15
    elif token in {'Th', 'Ti', 'Tu', 'Ty', 'Ts', 'TS', 'TE'}:
        value = -0.75
    elif token == '.T':
        value = -2.3 if prev.endswith('testing') else -1.0
    elif len(token) == 2 and token[1] == 'T' and token[0] in '/<({[,':
        value = -0.95
    elif token in {'-T', '_T', '*T'}:
        value = -0.7
    elif token in {'-t', '_t', '.t', '/t', ',t'}:
        value = -0.35
    elif token == 'Т':  # Cyrillic capital Te
        value = -0.83 if raw.startswith(' ') else -0.5
    elif token in {'ت', 'الت'}:  # Arabic ta, alone or with the article
        value = -0.5
    elif token in {'t', 'th', 'te', '(t'}:
        value = -0.14
    else:
        value = 0.0
    return None, float(value)

"""A positive response to explicit conversation, reasoning, and tool boundaries.

The response is smaller near the beginning of a document. Message endings
immediately after tool markup are weaker than endings after ordinary prose.
All non-boundary tokens are assigned zero.
"""
READS = ()

BOUNDARIES = {
    '<|im_start|>': 2.95,
    '<|im_end|>': 3.30,
    '<think>': 3.25,
    '</think>': 3.15,
    '<tool_call>': 3.65,
    '</tool_call>': 3.22,
    '<tool_response>': 4.20,
    '</tool_response>': 4.65,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        position, previous = carry[1] + 1, carry[2]
    token = prefix.token_strings[-1]
    value = BOUNDARIES.get(token, 0.0)
    if token in BOUNDARIES:
        value -= 1.8 / (position + 1) ** 0.65
        if token == '<|im_start|>' and position == 0:
            value = 0.407
        if token == '<|im_end|>':
            if previous == '</tool_response>':
                value -= 1.02
            elif previous == '</tool_call>':
                value -= 0.95
    return (doc, position, token), float(value)

