"""Approximate a leading-zero detector using the two preceding tokens.

Zero is strong at numeric-field starts, weaker after decimal punctuation or
space-separated numbers, and nearly silent after digits. Brackets strengthen
it; letters and colons weaken it. An initial run of ASCII zeros gets 1.37.
Fullwidth zero behaves similarly. Smaller responses mark subscript zero,
à/À, and the JSON opening {". All other tokens get zero.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, before_previous, only_zeros = '', '', True
    else:
        _, previous, before_previous, only_zeros = carry
    end = previous[-1:]

    value = 0.0
    if token in ('0', '０'):
        if only_zeros and token == '0':
            value = 1.37
        elif end.isdigit():
            value = -0.03
        elif previous.isspace() and before_previous[-1:].isdigit():
            value = 1.23
        elif end in ('.', ',', '．', '，'):
            value = 1.25
        elif end in ('(', '[', '{', '（', '［'):
            value = 2.57
        elif end in (':', '：') or end.isalpha():
            value = 1.85
        else:
            value = 2.25
    elif token == '₀':
        value = 0.15 if end.isdigit() else 1.22
    elif token.strip().lower() == 'à':
        value = 0.88 if token == ' à' else 0.60
    elif token == '{"':
        value = 0.35

    return (doc, token, previous, only_zeros and token == '0'), value

