"""A negative detector for the spelling 'ire', strongest on fire and wire.

For isolated 'ire' suffix pieces, short preceding word fragments strengthen
the response; long ones weaken it. Inflections and compounds are weaker.
Other spellings get zero, rather than modeling small miscellaneous responses.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower().lstrip('_/-')
    if word in {'ire', 'ires', 'ired', 'iring'}:
        previous = ''
        if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]
        fragment = re.search(r'[A-Za-z]+$', previous)
        n = len(fragment[0]) if fragment else 3
        strength = 0.5 + 3.9 / max(n, 1) ** 0.4
        if word in {'ired', 'iring'}:
            strength *= 0.8
        if token[:1].isspace():
            strength = 3.1
        return None, -strength
    if word in {'fire', 'wire'}:
        return None, -4.5
    if re.fullmatch(r'[fhwtd](ire[ds]?|iring)', word):
        return None, -2.8
    if word in {'aire', 'uire', 'iren', 'pire', 'ewire'}:
        return None, -1.8
    if word in {'pired', 'piring'} or word.startswith('retir'):
        return None, -1.4
    if re.fullmatch(r'(asp|insp|exp|emp|des|adm|vamp)ire', word):
        return None, -0.7
    if word in {'aires', 'shire', 'oire', 'iere'}:
        return None, -0.7
    if 'fire' in word or 'wire' in word:
        return None, -0.8
    return None, 0.0

