"""A spelling-sensitive response to 'here', 'there', and short 'ere' fragments.

Place-pointing adverbs give positive responses, including several translations.
Short 'ere' spellings also fire inside unrelated words; extra letters and
accents generally weaken them. This is not a general location recognizer:
'where' does not fire. A preceding clause opener boosts 'there', whereas
be-verbs and 'out' lower it. Capitalized fragments boost a following 'ere'.
"""
import re
import unicodedata
from functools import lru_cache

READS = ()
HERE_WORDS = frozenset(('hier', 'ici', 'aqui', 'aquí', 'здесь', 'هنا', '여기'))
CLAUSE_OPENERS = frozenset(('if', 'when', 'that', 'because', 'since', 'unless'))
BE_VERBS = frozenset(('is', 'are', 'was', 'were', 'am', 'been', 'being'))


@lru_cache(maxsize=4096)
def lexical_value(token):
    text = token.strip()
    word = text.lower()
    spaced = token.startswith(' ')
    bare = word.lstrip('.\"“_')
    if bare != word:
        return 0.75 * lexical_value(bare)
    if word == 'here':
        return 2.33 + (0.6 if text.isupper() and spaced else
                       0.2 if text[:1].isupper() and spaced else 0.0)
    if word == 'there':
        return 1.24 if spaced else 1.15
    if word in HERE_WORDS and (spaced or word not in ('ici', 'aqui')):
        return 0.9
    if '这里' in word or '這裡' in word:
        return 1.25
    if word in ('ここ', 'ここで', 'これ', '这儿', '在此'):
        return 0.85
    if word in ('此', 'こちら'):
        return 0.6
    if word == 'were':
        return 0.1 if spaced else 0.32
    if word == 'mere':
        return 3.7 if spaced else 3.4
    if word in ('hereby', 'herein', 'merely'):
        return 0.9 if word == 'hereby' else 0.67 if word == 'herein' else 0.54

    # The spelling family, rather than its meaning, explains these responses.
    decomposed = unicodedata.normalize('NFD', word)
    plain = ''.join(c for c in decomposed if not unicodedata.combining(c))
    accents = len(decomposed) - len(plain)
    if re.fullmatch('[a-z]?ere', plain) and word != 'where':
        value = 3.14 if len(plain) == 3 else 2.15
        if len(plain) == 4 and plain[0] in 'aeiou':
            value *= 0.75
        if text[:1].isupper() and spaced:
            value += -1.3 if len(plain) == 3 else 0.5
        return value * 0.6 ** accents
    if re.fullmatch('ere[a-z]', plain):
        return (0.62 if plain.endswith('d') else 1.35) * 0.9 ** accents
    if plain == 'ieren':
        return 0.5
    if plain.startswith('ere') and plain.isalpha() and 5 <= len(plain) <= 6:
        return 0.7 * 0.7 ** (len(plain) - 5) * 0.6 ** accents
    if not spaced and re.fullmatch('er[aiouy]', plain):
        return 0.5
    if not spaced and re.fullmatch('[aoi]re', plain):
        return 0.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = lexical_value(token)
    if word == 'there':
        before = previous.strip().lower()
        if before in CLAUSE_OPENERS:
            value += 0.15
        elif before in BE_VERBS or before == 'out':
            value -= 0.4
        elif before == 'from':
            value -= 0.3
    elif word == 'ere' and not token.strip()[:1].isupper():
        fragment = previous.strip()
        if fragment[:1].isupper():
            value += 0.65
        elif len(fragment) >= 4:
            value -= 0.3
    return (doc, token), float(value)

