"""Token openings: split East Asian characters and compound punctuation.

Unfinished characters in recent Japanese/Chinese or Korean text are positive;
completion bytes are not. A few explicit UTF-8 lead classes cover Latin text
and Runic. Syntax rules recognize repeated heading/separator signs, punctuation
before an opening parenthesis, and quotes introducing paths, flags or objects.
Words otherwise predict zero. State resets at each new document. This coarse
approximation leaves out individual-word and finer contextual variation.
"""

READS = ()


def punctuation(token):
    s = token.strip()
    if s == '<think>':
        return 0.35
    if s in {'</tool_call>', '</tool_response>'}:
        return -0.15
    if not s or any(c.isalnum() for c in s):
        return 0.0
    if len(set(s)) == 1:
        n = len(s)
        if s[0] == '-' and n >= 2:
            value = 0.75 if n == 2 else (0.56 if n == 3 else 0.80)
            return value * (0.42 if '\n' in token else 1.0)
        if s[0] == '#' and n >= 2:
            return (0.70 if n == 3 else 0.42) * (0.3 if '\n' in token else 1.0)
        if s[0] == '=' and n >= 4:
            return 0.70
    if '(' in s[1:] and '()' not in s:
        before = s[:s.rfind('(')]
        if any(c in before for c in ')]'):
            return 0.92
        if before[-1] in '!(': 
            return 0.76
        if before[-1] in '= $`[>:{-*/.^_}':
            return 0.60
    if '{"' in s or "{'" in s:
        return 0.69 if token.startswith(' ') else 0.46
    if '["' in s or "['" in s:
        return 0.66
    if '][' in s and '[]' not in s:
        return 0.91
    if '},{' in s or '}_{' in s or '}{' in s:
        return 0.46
    if ':{' in s:
        return 0.61
    for quote in ('"', "'"):
        if quote in s:
            rest = s.split(quote, 1)[1]
            if rest.startswith('--'):
                return 1.42
            if rest.startswith(('./', '../')):
                return 0.95
            if rest.startswith(('/', '$', '#', '@', '<', '{', '[', '%')):
                return 0.58
    if '《' in s:
        return 0.74
    return 0.34 if s == '&&' else (0.22 if s == '||' else 0.0)


def step(carry, prefix, upstream):
    token, tid = prefix.token_strings[-1], prefix.token_ids[-1]
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    recent, pending = ('', False) if fresh else carry[1:]
    value = punctuation(token)
    unfinished = False
    if '\ufffd' in token:
        decoded = prefix.text_prefixes[-1]
        unfinished = decoded.endswith('\ufffd')
        if (token.strip() == '\ufffd' and unfinished and not pending
                and tid not in {5691, 29333}):  # Literal replacement characters.
            for char in reversed(recent):
                n = ord(char)
                if 0x3040 <= n <= 0x30ff or 0x3400 <= n <= 0x9fff:
                    value = 0.04 if token.startswith(' ') else 1.70
                    break
                if 0xac00 <= n <= 0xd7af:
                    value = 0.86 if token.startswith(' ') else 0.70
                    break
        count = len(token) if fresh else (
            len(recent) + len(decoded) - len(prefix.text_prefixes[-2]))
        recent = decoded[-min(32, max(1, count)):]
    else:
        recent = (recent + token)[-32:]
    # Named encoding classes, not individual learned word responses.
    if 160 <= tid <= 165:  # Single UTF-8 lead bytes E4..E9.
        value = 1.60
    elif tid == 126:  # Single lead byte C2, e.g. a split nonbreaking space.
        value = 0.58
    elif tid in {9843, 25917}:  # Space + Latin Extended-A lead C4/C5.
        value = 0.74
    elif tid in {124308, 124999}:  # Ogham/Runic prefixes E1 9A / E1 9B.
        value = 1.25
    elif tid in {3315, 5140, 10764}:  # Space + Hangul lead EB/EC/ED.
        value = 0.30
    elif token == '<|im_start|>':
        value = 0.15 if fresh else 0.51
    elif fresh and token in {'##', '###'}:
        value = 0.08
    return (doc, recent, unfinished), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 5104 (Qwen3-1.7B).

What it responds to, in plain terms:

1. Half-written non-ASCII characters. Text is byte-level, so a Chinese, Japanese or
   other multi-byte character is often split across tokens, and a token can end
   inside one (its bytes decode alone to U+FFFD). When a token opens such a character,
   the component fires, harder when the surrounding text is CJK.
2. Code and markdown glue: tokens made only of symbols that chain brackets, quotes
   or braces, such as ' {"', ')(', '][', '](', "['", or runs of dashes, hashes,
   equals signs and slashes ('--', '###', '=========').
3. The chat-template marker '<|im_start|>'.

Everything else is near zero. The program predicts these levels; it is not a
reimplementation of the model.
"""

import re

READS = ()

CHAT_START = "<|im_start|>"
BRACKETS = set("()[]{}")
RUN = re.compile(r"(-{2,}|#{2,}|={2,}|/{2,})")
GLUE = re.compile(r"[^\s\w([{][([{]|\s[\[{]['\"]|^[\[{]['\"]")


def is_cjk(c):
    return "\u3040" <= c <= "\u30ff" or "\u3400" <= c <= "\u9fff" or "\uac00" <= c <= "\ud7af"


def cjk_share(text):
    """Share of CJK characters among the last 30 non-space characters."""
    chars = [c for c in text[-40:] if not c.isspace() and c != "\ufffd"][-30:]
    if not chars:
        return 0.0
    return sum(is_cjk(c) for c in chars) / len(chars)


def is_symbol_glue(s):
    """Symbol-only token that runs dashes, hashes, equals or slashes, or joins an opening
    bracket to a symbol before it (')(', '][', '/(', ' {"', "['")."""
    s = s.strip()
    if not s or any(c.isalnum() for c in s) or "\ufffd" in s:
        return False
    return bool(RUN.fullmatch(s) or GLUE.search(s))


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok == CHAT_START:
        return carry, 0.45
    if "\ufffd" in tok:
        text = prefix.text_prefixes[-1]
        if not text.endswith("\ufffd"):
            return carry, 0.0  # a stray byte after a finished character
        if prefix.position > 0 and prefix.text_prefixes[-2].endswith("\ufffd"):
            return carry, 0.2  # finishing a character that was already open
        if tok.startswith(" "):
            return carry, 0.1 + 0.4 * cjk_share(text)
        return carry, 0.5 + 1.0 * cjk_share(text)
    if is_symbol_glue(tok):
        return carry, 0.3
    return carry, 0.0

