            value = 0.62 if s[1] in '前后後中上下外间間内內一' else 1.30
        if s.endswith(('的', '了', '于', '於')) and not s.endswith('目的'):
            value *= 0.35
        return value
    if s[0] in PARTICLES:
        single, compound = PARTICLES[s[0]]
        if len(s) == 1:
            return single
        if all(c in 'がにをのとはでも' for c in s):
            return 0.02
        if s.endswith(('ます', 'ません', 'ました')):
            return 0.07
        if s[0] in 'がに' and len(s) == 2:
            return 1.5 if s[0] == 'が' else 1.0
        if any('\u3400' <= c <= '\u9fff' for c in s):
            return 0.75 if s[0] == 'が' else 0.49
