            return 0.20
        if m[1] == 'To' and not s.startswith('.'):
            return 1.65 if len(s) <= 7 else 0.85
        return 0.43 if len(s) > 12 else 0.78
    if s == '.yml':
        return 0.52  # YAML extension
    if re.fullmatch(r'@[A-Za-z]+', s):
        return 0.50  # annotations and directives
    if re.fullmatch(r'(here|there)(of|in|by|to|with|after|upon)', s):
        return 0.50  # demonstrative/preposition compounds
    return 0.0


def step(carry, prefix, upstream):
    return None, float(activation(prefix.token_strings[-1]))

