"""Collection-API detector: fires on the words of maps, sets, lists and their operations
(map, dict, key, put, get, insert, add, append, size ...). It fires more on a method call
(a word right after a dot, as in `m.put(`), and more when container words already appear
in the same document nearby. Everything else predicts 0."""

READS = ()

# words for container types and key-value / collection operations, with a rough strength
STRONG = {"map", "dict", "hashmap", "treemap", "iterator", "keys", "entries", "key",
          "insert", "append", "collection", "collections", "stream", "join", "getall",
          "enumerate", "remove", "sorted"}
MEDIUM = {"set", "list", "get", "put", "add", "size", "count", "array", "push", "update",
          "empty", "replace", "parse", "length", "filter", "copy", "unique", "distinct",
          "optional", "vec", "pair", "counter", "stack", "entry", "tuple"}
# container types whose presence nearby boosts the response
TYPE_WORDS = {"map", "set", "list", "dict", "collection", "hashmap", "treemap", "hashset",
              "collections", "iterator", "entries", "keys"}


def _word(token):
    return token.strip(" ._/(\t\n").lower()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = _word(token)
    if word in STRONG:
        value = 1.0
    elif word in MEDIUM:
        value = 0.6
    else:
        return carry, 0.0
    if token.startswith("."):
        value *= 1.2
    elif token.startswith(" "):
        value *= 0.7
    doc = prefix.document_ids[-1]
    near = 0
    for tok, d in zip(prefix.token_strings[-41:-1], prefix.document_ids[-41:-1]):
        if d == doc and _word(tok) in TYPE_WORDS:
            near += 1
    value *= 1.0 + 0.15 * min(near, 4)
    return carry, float(value)

"""Layer-0 MLP down_proj component 5107: a citation and figure-reference detector.

Plain-terms summary. This unit goes negative when a scientific paper points at a
numbered figure, table or reference. It is most negative on the words "Fig", "Figure",
"Table" themselves, and on the number right after them ("Figure 2"). Numbers after an
opening "(" or "[" ("[3", "(12"), or a few words after "et al" ("Smith et al. 2013"), are
also negative, and numbers inside brackets or in running academic prose are mildly
negative. Numbers after a month name ("June 2013") are mildly positive, and so are organism
words ("human", "mouse", "rat"), which often come before a biomedical noun. Everything
else stays at zero: most words, punctuation and code, because they follow no simple rule.

The program reads the current token, the last few non-space tokens of the same document,
a 15-token window for prose-ness, and the bracket depth within the document.
"""
READS = ()

FIGURE_WORDS = {"Fig", "Figure", "fig", "Figures", "Table", "table"}
OPENERS = {"(", "[", "[@", ".[", "(@", "(["}
CITATION_WORDS = {"al", "et", "ref", "refs", "F", "T"} | FIGURE_WORDS
MONTHS = {"January", "February", "March", "April", "May", "June", "July",
          "August", "September", "October", "November", "December"}
ORGANISMS = {"human", "Human", "mouse", "rat"}
PROSE_WINDOW = 15


def _is_word(s):
    s = s.strip()
    return len(s) > 2 and s.isalpha()


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    t = len(toks) - 1
    tok = toks[t].strip()
    # carry: (bracket depth, document of the last token)
    depth, doc = carry if carry is not None else (0, None)
    if doc != docs[t]:
        depth = 0
    # the last four non-space tokens of this document, nearest first
    back = []
    for k in range(1, 12):
        if t - k < 0 or docs[t - k] != docs[t] or len(back) == 4:
            break
        if toks[t - k].strip():
            back.append(toks[t - k].strip())
    if tok in FIGURE_WORDS:
        value = -0.46
    elif tok.isdigit():
        if back and back[0] in FIGURE_WORDS:
            value = -0.6
        elif back and back[0] in OPENERS:
            value = -0.12
        elif any(w in CITATION_WORDS for w in back):
            value = -0.37
        elif depth > 0:
            value = -0.08
        elif (back and back[0] in MONTHS) or (len(back) > 1 and back[1] in MONTHS):
            value = 0.19
        else:
            value = -0.03
        window = toks[max(0, t - PROSE_WINDOW):t]
        if window and sum(_is_word(w) for w in window) / len(window) >= 0.4:
            value -= 0.09
    elif tok in ORGANISMS:
        value = 0.34
    else:
        value = 0.0
    for ch in toks[t]:
        if ch in "([":
            depth += 1
        elif ch in ")]":
            depth = max(0, depth - 1)
    if "\n" in toks[t]:
        depth = 0
    return (depth, docs[t]), value

