"""Give numerals a weak negative score, stronger for bracketed refs and figures."""
import re

READS = ()

_BRACKETED = re.compile(
    r"\[\s*(?:@[\w.-]*)?(?:\d+(?:\s*,\s*@?[\w.-]*\d*)*)?$",
    re.IGNORECASE,
)
_REF_LINK = re.compile(r"\]\(#\w*$", re.IGNORECASE)
_FIGURE_LABEL = re.compile(r"\bfig(?:ure)?\.?\s*$", re.IGNORECASE)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    before = ""
    if carry is not None and carry[0] == document:
        before = carry[1]

    token = prefix.token_strings[-1]
    value = 0.0
    if token.isdecimal():
        trimmed = before.rstrip()
        if _BRACKETED.search(before):
            value = -0.36
        elif _REF_LINK.search(before):
            value = -0.40
        elif _FIGURE_LABEL.search(before):
            value = -0.45
        elif trimmed.endswith("="):
            value = 0.03
        elif before.endswith(("\n", "\r")):
            value = 0.04
        elif trimmed.endswith((",", "/")):
            value = -0.07
        elif trimmed.endswith(("-", "−", "–")):
            value = -0.16
        elif trimmed.endswith("("):
            value = -0.08
        elif before.endswith(tuple(".·")):
            value = -0.025
        elif trimmed and trimmed[-1].isalpha():
            value = -0.07 if trimmed == before else -0.10
        else:
            value = -0.05
    elif token.strip().casefold() in {"fig", "fig.", "figure"}:
        value = -0.30
    elif token.rstrip().endswith("[") and any(c in token[:-1] for c in ".,"):
        value = -0.36

    tail = (before + token)[-80:]
    return (document, tail), value

