"""Predict a negative response to standalone backslashes and repeated escapes.

The slash count sets the main strength. Preceding math delimiters and line
breaks strengthen it; a newline in the same token weakens it. Literal text
escapes weaken single slashes. A small correction handles document starts.
Only 256 preceding characters are retained, resetting at document boundaries.
Ordinary tokens and single slashes merged with other characters predict zero.
"""
import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, position = '', '', 0
    else:
        _, tail, previous, position = carry
    token = prefix.token_strings[-1]
    text = token.strip()
    n = len(text) - len(text.rstrip('\\'))
    value = 0.0
    if text == '＼' or (n and (text == '\\' * n or n >= 2)):
        value = {1: -0.95, 2: -1.60, 3: -1.10}.get(n, -1.95)
        if text == '＼':
            value = -0.70
        if token.startswith(' '):
            value -= 0.15
        if '\n' in token:
            value += 0.80
        if '\n' in previous or ('$' in previous and '\\$' not in previous):
            value -= 0.45
        if previous.endswith('{'):
            value -= 0.20
        if previous and previous[-1] in ')]};':
            value += 0.15
        if previous[-1:].isalnum():
            value += 0.10
        if '$' in tail:
            value -= 0.10
        if '\\' in tail:
            value += 0.10
        if n == 1 and not token.startswith(' '):
            if '\\n' in tail or '\\t' in tail:
                value += 0.15
        if '\\x' in tail:
            value += 0.15
        value -= 0.40 / math.sqrt(position + 1)
        if position == 0:
            value += 0.70
    return (doc, (tail + token)[-256:], token, position + 1), float(value)

