    'or': 0.68, 'nor': 0.36, 'ou': 0.43, 'oder': 0.40,
    'или': 0.57, 'либо': 0.40, 'eller': 0.46, 'vagy': 0.47,
    '또는': 0.65, '혹은': 0.59,
}
