# Common Indonesian function words and verbs.
ID_AUX = set('menjadi merupakan bisa harus tidak tersebut seperti oleh '
             'memiliki telah masih sudah'.split())
ID_LINKS = set('dengan pada untuk itu kita akan dalam atau adalah hanya '
               'lebih dapat dari juga sebagai kepada'.split())

