AR_PARTICLES = {
    'على': 1.75, 'إلى': 1.38, 'أو': 1.78,
    'في': 0.91, 'من': 0.65, 'عن': 0.65, 'مع': 0.82,
    'أن': 1.15, 'إن': 1.29, 'أنه': 1.74,
    'هو': 1.41, 'هي': 1.41, 'لا': 1.22, 'لم': 0.87,
    'ما': 0.79, 'كل': 0.90, 'التي': 0.58, 'الذي': 0.86,
    'هذا': 0.8, 'هذه': 0.78, 'ذلك': 0.95,
