               'وال': 0.75, 'بال': 1.39, 'لل': 1.0,
               'ت': 0.48, 'أ': 0.72, 'إ': 1.0}
THAI_AUXILIARIES = 'เป็น จะ ได้ ให้ ถึง'.split()
THAI_GRAMMAR = (
    'เป็น จะ ได้ ให้ ไม่ หรือ และ ใน จาก ของ โดย เพราะ ไป ทำ '
    'คือ กับ ที่ ซึ่ง แต่ ว่า แล้ว ยัง ก็ ใช่ เลย ตาม'
