"""layers.0.mlp.down_proj:5110 -- a lexical "or / function word" detector.

What it does: the component reads the token at each position (layer 0 is almost
entirely token-driven) and responds to three kinds of word:

1. Disjunction "or" and its translations: English " or" (about 0.7), capitalised
   and upper-case variants, French/German/Indonesian/Greek-style "ou", "oder",
   "nor", "atau", Russian "или", Chinese "或", Arabic "و"/"أو", plus
   "Alternatively" and Spanish/Portuguese " que" (about 0.5 each).
2. Grammatical function words in Vietnamese, Indonesian/Malay and Arabic
   (e.g. Vietnamese " là", " và", " của", " có"; Indonesian " dengan",
   " yang", " menjadi"; Arabic " في", " على", " من"). These are strongest (about 1.2).
3. Any Thai-script token (about 0.45), Arabic-script tokens (about 0.18), and
   tokens with Vietnamese-only letters (about 0.3), as coarse averages.

Everything else predicts 0. English function words ("the", "of", "to", "and") and
most content words sit near 0 in the data, so they are left at 0.

The values are the average activations measured on training text; the program
does no model computation and reads no state.
"""

import unicodedata

READS = ()

# Disjunction "or" and cross-lingual equivalents, with typical activations.
OR_WORDS = {
    " or": 0.68, " OR": 0.6, "Or": 0.75, " Or": 0.72,
    " ou": 0.45, " oder": 0.40, " nor": 0.37, " atau": 1.3,
    " или": 0.59, "或": 0.6, " و": 0.7,
    "Alternatively": 0.55, " Alternatively": 0.55, " que": 0.54,
}

# Function words of Vietnamese, Indonesian/Malay and Arabic.
VI_FUNC = {
    " là", " và", " của", " có", " cũng", " để", " trong", " cho", " với", " này",
    " một", " được", " đã", " không", " đang", " cần", " đến", " vào", " tôi", " chỉ",
    " ra", " về", " những", " bằng", " phải", " lại", " thấy", " mà", " nhưng", " còn",
    " rất", " đi", " làm",
}
ID_FUNC = {
    " dengan", " pada", " dalam", " untuk", " yang", " dari", " itu", " ini", " adalah",
    " bisa", " harus", " menjadi", " tersebut", " juga", " sau", " dan", " akan", " hanya",
    " tidak", " oleh", " seperti", " kita", " kepada", " menggunakan",
}
AR_FUNC = {" في", " على", " إلى", " أن", " قد", " من", " ب", " ل", " و", " أو", " التي", " بال"}

VI_LETTERS = set("ạảấầẩẫậắằẳẵặẹẻẽếềểễệỉịọỏốồổỗộớờởỡợụủứừửữựỳỵỷỹđơưăâêôĂÂĐÊÔƠƯ")


def script(s):
    """The Unicode script name of the first letter in a token, e.g. 'THAI' or 'ARABIC'."""
    for ch in s:
        if ch.isalpha():
            try:
                return unicodedata.name(ch).split()[0]
            except ValueError:
                return ""
    return ""


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if s in OR_WORDS:
        return None, float(OR_WORDS[s])
    if s in VI_FUNC or s in ID_FUNC or s in AR_FUNC:
        return None, 1.2
