def tabs(s, previous):
    if s == '\t':
        if not previous:
            return 0.02
        if previous.endswith('\n'):
            return -0.23
        return 0.08 if previous.isspace() else -0.43
    count = s.count('\t')
    if count > 1:
        return -0.03 if count == 2 else 0.08
    if s.startswith(' '):
        return -0.16
    if '\n' in s or '\r' in s:
        return -0.28 if previous[-1:].isdigit() else -0.13
    spaces = s.count(' ')
    if spaces >= 7:
        return 0.035 if spaces == 15 else -0.06
    return {1: -0.49, 2: -0.45, 3: -0.64,
            4: -0.32, 5: -0.165}.get(spaces, -0.10)


