    if l.endswith(('sy', 'shi')) and n <= 4 and not s.startswith(' '):
        return -0.50
    if l in {'sí', 'sì'} or n <= 4 and l.endswith(('sí', 'sì', 'sı')):
        return -1.05
    if l == 'się':
