    'culture', 'society', 'market', 'markets', 'middle', 'vacuum',
    'presence', 'absence', 'scenarios', 'environmental', 'surrounding',
}
WEAK_SETTINGS = {
    'world', 'state', 'states', 'fields', 'realm', 'space', 'spaces',
    'terrain', 'ambient', 'background', 'medium', 'habitat', 'ecology',
}
NOUNS = (ENVIRONMENT | SITUATION | CIRCUMSTANCES | DYNAMIC_SETTINGS |
         LOCAL_SETTINGS | GENERAL_SETTINGS | WEAK_SETTINGS | {'conditions'})
SETTING_MODIFIERS = {
    'work', 'working', 'learning', 'social', 'urban', 'hostile', 'dynamic',
    'adverse', 'collaborative', 'supportive', 'natural', 'competitive',
}
