    (ENVIRONMENT | SITUATION, 1.8), (CIRCUMSTANCES, 1.2),
    (DYNAMIC_SETTINGS, 0.85), (LOCAL_SETTINGS, 0.65),
    (GENERAL_SETTINGS, 0.45), (WEAK_SETTINGS, 0.27),
