        return 0.9
    if token in ('ii', 'iii', 'iv', 'vi', 'vii', 'viii', 'ix', 'II', 'III', 'IV'):
        return 0.7
    if token == '-':
        return 2.30
    if token in ('+', '*'):
        return 1.61
    if token == '>':
        return 1.51
    if token == '#':
        return 1.27
    if token in ('%', '·', '_', '–', '—', '−', '/'):
        return 1.35
    if token in ('!', '.', '~', '・'):
        return 1.10
    if token == ' ':
        return 1.01
    if token == '//':
        return 0.96
    if token in ("'", '|', '=', '--', '•'):
        return 0.89
    if token in ('\\', ':', '**'):
        return 0.74
    if token in ('(', '"', '}', '`', ' *'):
        return 0.62
    if token in ('[', '<', '“', '@', '__', '---', '===', ' //'):
        return 0.50
