        return 0.30 if token in 'ABCD' else 0.10
    if token.startswith('-') and len(token) == 2 and token[1].isalpha():
        return 0.9
    if token.endswith('\n') and token.rstrip('\n') in ('-', '+', '>', '#', '/'):
        return 0.9 if token == '-\n' else 0.45
