    if char == "#":
        return "hash"
    if char in "\"'`":
        return "quote"
    if unicodedata.category(char).startswith("P"):
        return "punct"
    if unicodedata.category(char).startswith("S"):
        return "symbol"
    return first_class(text)


PAIR_MEANS = {
    ("angle", "angle"): 0.0442,
    ("punct", "punct"): -0.0297,
    ("underscore", "slash"): 0.0287,
    ("symbol", "letter"): 0.0241,
    ("angle", "leading-space"): -0.0217,
    ("Mn", "letter"): -0.0207,
    ("letter", "empty"): 0.0195,
    ("angle", "letter"): 0.0182,
    ("slash", "sentence-punct"): -0.0138,
    ("angle", "sentence-punct"): 0.0136,
    ("digit", "open-bracket"): 0.0133,
    ("letter", "open-bracket"): 0.0132,
    ("operator", "sentence-punct"): 0.0131,
    ("letter", "operator"): 0.0126,
    ("digit", "letter"): 0.0119,
    ("close-bracket", "underscore"): -0.0114,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "<think>":
        return None, -0.135
    current_class = word_class(token)
    previous = ""
    if prefix.position and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2]
    pair = (current_class, word_class(previous))
    if pair in PAIR_MEANS:
        return None, PAIR_MEANS[pair]
    return None, MEAN_BY_CLASS.get(first_class(token), 0.0011)

programs.sol:
"""Primarily a less-than / opening-angle-bracket detector.

Comparisons and generic-type openings are strongest; markup is weaker.
Comparative 'than', equality, percentages, arrows and opening brackets give
smaller responses. Token spacing and fused punctuation affect the magnitude.
Training examples concentrate their large responses on these signs.
A 300-character tail supplies syntax context, reset at each document.
"""
import re

READS = ()
WORD = re.compile(r'[A-Za-z_][A-Za-z_0-9]*$')
MARKUP = re.compile(r'</(?!(?:tool_call|tool_response|think)>)[A-Za-z]'
                    r'|<[A-Za-z][^<>\n]*=[\\"\x27]'
                    r'|<(?:p|tr|td|div|span|br|nil)>')
TYPES = set('bool byte char double float int long object short string '
            'unsigned void'.split())
# Familiar signs: (unspaced response, space-prefixed response).
SIGNS = {
    '=': (0.37, 0.455), ':=': (0.44, 0.58), '!=': (0.35, 0.35),
    '≤': (0.65, 0.65), '≥': (0.4, 0.4), '>=': (1.05, 1.05),
    '＜': (2.9, 2.9), '〈': (1.65, 1.65), '⟨': (1.65, 1.65),
    '«': (0.49, 0.49), '[': (0.15, 0.31),
}


def opening_angle(s, text, word):
    t = s.strip()
    left, right = t.split('<', 1)
    markup = bool(MARKUP.search(text))
    blank = not text.split('\n')[-1].strip()
    if t.startswith('<|'):
        return 0.0                    # conversation boundary, not a relation
    if t == '<tool_call>':
        return 0.94
    if right.startswith('>'):
        return 1.7 if t == '<>' else 0.7   # empty type-parameter list
    if '>' in right:
        return 0.1                    # complete tag fused into a token
    if right.startswith('='):
        return 1.45 if s.startswith(' ') else 1.8
    if right[:1] in ('<', '-', '!', '?'):
        return {'<': 1.1, '-': 2.0, '!': 2.2, '?': 0.6}[right[0]]
    if right.startswith('/'):
        return 0.3 if markup else (1.7 if blank else 0.9)
    if left:
        return 0.65 if '>' in left else 2.3
    if not right:
        if not text:
            return 1.0
        if '\n' in s:
            return 2.5                # diff-line marker
        if markup:
            return 1.4 if blank else 2.6
        if text[-1:].isspace():
            return 2.6 if blank else 3.3
        return 4.35 if s.startswith(' ') or len(word) == 1 else 3.6
    if markup and not (right[0].isupper() and word[:1].isupper()):
        return 0.6
    value = 2.6 if right in TYPES else 3.2
    if len(right) == 1 and right.isupper():
        value = 3.45
    if text.rfind('<') > text.rfind('>'):
        value -= 0.8                  # nested type parameters
    return value


def token_value(s, text):
    t = s.strip()
    spaced = int(s.startswith(' '))
    text = text.replace('\\n', '\n').replace('\\r', '\n')
    prev = text.rstrip()
    match = WORD.search(prev)
    word = match[0] if match else ''
    if t.lower() == 'than':
        if word.lower() == 'rather':
            return 0.0
        if word.lower() == 'other':
            return 0.24
        return 1.1 if word.lower() in ('less', 'more', 'greater', 'fewer') else 0.8
    if '<' in t:
        return opening_angle(s, text, word)
    if t in SIGNS:
        return SIGNS[t][spaced]
    if t.endswith('->'):
        return 0.56 if spaced else 0.39
    if t == '=>':
        return 0.08 if spaced else 0.36
    if t == '>':
        if spaced:
            return 1.5
        opening = text.rfind('<')
        if opening > text.rfind('>') and '\n' not in text[opening:]:
            return -0.25              # closing an angle-bracketed expression
        return 0.2 if '\n' in s else 1.3
    if t.startswith('>&'):
        return 0.9
    if '%' in t:
        return (0.81 if spaced else 0.70) if t == '%' else 0.43
    if '《' in t:
        return 1.3
    if t == 'langle' and prev.endswith('\\'):
        return 1.6
    if len(t) >= 2 and set(t) == {'\\'}:
        return 0.64
    if t.startswith('{\\'):
        return 0.3 if spaced else -0.03
    if t == '{':
        if word == 'return' or prev.endswith(':'):
            return -0.03              # object/dictionary, not a code block
        if '\n' in s:
            return 0.53 if prev.endswith(')') else 0.34
        return 0.12 if spaced else -0.03
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    return (doc, (text + s)[-300:]), float(token_value(s, text))

programs.luna:
"""A cautious surface cue for comparison signs and opening delimiters."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    bare = token.lstrip()

    if "->" in token or "→" in token:
        value = 0.32
    elif "<" in token:
        tail = token.rsplit("<", 1)[1].lstrip()
        if "'" in token or '"' in token:
            value = 2.0
        elif tail.startswith("/"):
            value = 2.35
        elif tail[:1].islower():
            value = 0.32
        elif token[:1].isspace():
            value = 3.0
        else:
            value = 2.4
    elif ">" in token:
        value = 2.0 if token[:1].isspace() else 0.10
    elif "=" in token:
        value = 0.40
    elif any(mark in token for mark in ("≤", "≥", "≠", "≈")):
        value = 0.45
    elif bare.startswith("%"):
        value = 0.65
    elif bare.startswith("&#"):
        value = 0.50
    elif bare.startswith(("[", "{")):
        value = 0.32
    elif bare.startswith(("(", "«", "《", "“", "\"")):
        value = 0.40
    elif bare.lower() == "than":
        value = 0.95
    else:
        value = 0.0

    # The token is only a rough clue, so temper each positive estimate.
    return None, float(value * 0.33)

programs.sol:
"""Approximate a mostly negative time/resource vocabulary feature.
Time units, weekdays, and clock identifiers supply lexical values.
Selected multilingual time/leave forms and spatial resources also respond.
Immediate modifiers distinguish allocated resources (full-time, work hours)
from calendar references (first time, next day). Initial tokens have stronger
negative values. Other tokens are zero; finer lexical distinctions are omitted.
"""
import re
READS = ()

TIME = {
    'time': -0.99, 'times': -0.20, 'timing': -0.40,
    'hour': -0.34, 'hours': -0.70, 'day': -0.51, 'days': -0.63,
    'week': -0.68, 'weeks': -0.74, 'month': -0.18, 'months': -0.31,
    'year': -0.24, 'years': -0.29, 'minute': -0.10, 'minutes': -0.28,
    'second': 0.02, 'seconds': -0.22, 'weekend': -0.88,
    'weekends': -0.80, 'afternoon': -0.46,
}
OTHER_TIME = set((
    'duration period periods morning evening night nights calendar semester '
    'holiday holidays vacation weekly timer timeout timestamp timezone'
).split())
WEEKDAYS = set((
    'monday tuesday wednesday thursday friday saturday sunday'
).split())
REFERENCE = set((
    'this that these those next last previous following recent same present '
    'first each every'
).split())
RESOURCE = set((
    'work worked working school academic office business paid leisure free '
    'spare available allotted limited renting commuting training outdoor '
    'indoor living dining'
).split())
POSSESSIVE = set('my your our his her their its'.split())
BENEFITS = set((
    'leave absence benefits disability housing insurance retirement pension'
).split())
ASIAN_TIME = {
    '时': -0.25, '時': -0.22, '日': -0.12, '天': -0.33,
    '休': -0.75, '假': -0.50, '暇': -0.65,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1].strip()
    word = s.strip('._/(-:[]{}\'"').lower()
    match = re.search(r'(\w+)\W*$', tail)
    prev = match.group(1).lower() if match else ''
    value = 0.0

    if '时间' in s or '時間' in s or word == '시간':
        value = -1.0
    elif s in ASIAN_TIME:
        value = -1.95 if s == '暇' and tail.endswith('休') else ASIAN_TIME[s]
    elif word in {'zeit', 'время', 'времени', 'tiempo', 'czas'}:
        value = -0.48
    elif word in WEEKDAYS:
        value = -0.75 if word == 'sunday' else -0.95
    elif 'datetime' in word:
        value = -0.50
    elif re.search(r'Time(?:[A-Z]|$)', s) and word != 'time':
        value = -0.55
    elif word in TIME or word in OTHER_TIME:
        value = TIME.get(word, -0.30)
        if word == 'time':
            if prev in {'full', 'half', 'part'}:
                value = {'full': -2.70, 'half': -2.40, 'part': -2.10}[prev]
            elif prev in RESOURCE:
                value = -1.95
            elif prev in {'first', 'same', 'next', 'hard', 'difficult', 'tough'}:
                value = -0.20
            elif prev in {'each', 'every', 'few', 'some', 'several'}:
                value = -0.38
            elif prev in {'this', 'last', 'long', 'over', 'any'}:
                value = -0.60
            elif prev in POSSESSIVE or prev in {'more', 'much', 'total'}:
                value = -1.40
            elif prev == 'the':
                value = -0.82
        elif prev in RESOURCE:
            value -= 1.0
        elif prev in REFERENCE:
            value += 0.33
        elif prev in {'a', 'an', 'per'}:
            value -= 0.20
    elif word in {'space', 'spaces', 'room', 'rooms'}:
        value = -0.22 if word.startswith('space') else 0.0
        if prev in RESOURCE:
            value -= 0.60
        elif prev in {'vector', 'dimensional', 'hilbert', 'phase', 'color'}:
            value += 0.31
    elif word in BENEFITS:
        value = -0.25
    if not tail and value < -0.1:
        value = 1.5 * value - 0.15
    return (doc, (tail + prefix.token_strings[-1])[-80:]), float(value)

programs.haiku:
"""Time-span detector v4: a lexicon of words for spans of time, graded by how strongly
they read as a duration, with 'time' used as an occurrence ('the first time') switched off."""
READS = ()

# "time" after these words is an occurrence (the first time, the same time, every time)
OCCURRENCE_BEFORE = {"first", "same", "next", "last", "every", "each", "another", "one",
                     "this", "that", "many", "some"}
WEEKDAYS = {"monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"}

# typical activation for span words (negative = the component fires)
SPAN_VALUE = {
    "hours": -0.7, "weeks": -0.8, "week": -0.6, "weekend": -0.7, "weekends": -1.0,
    "days": -0.7, "holidays": -0.6, "holiday": -0.3, "vacation": -0.5,
    "hour": -0.4, "hrs": -0.3, "day": -0.4, "minutes": -0.3, "minute": -0.1,
    "seconds": -0.25, "months": -0.36, "month": -0.15, "years": -0.3, "year": -0.2,
    "duration": -0.3, "timeframe": -0.6, "semester": -0.35, "daytime": -0.5,
    "times": -0.2, "decades": -0.2, "night": -0.2,
}

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().strip("-_.(").lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word == "time":
        if before in OCCURRENCE_BEFORE:
            value = -0.1
        elif token.strip()[:1].isupper() or token.isupper():
            value = -1.5
        else:
            value = -0.9
    elif "时间" in word or "時間" in word or "시간" in word:
        value = -1.0
    elif word in WEEKDAYS:
        value = -0.9
    else:
        value = SPAN_VALUE.get(word, 0.0)
    return carry, value

programs.sol:
"""Local spelling responses for split Latin-derived words.

Bare singular -ica/-ico pieces are positive, but recent acute, grave, or
circumflex vowel accents in the same word reverse that sign. Nominal -io,
-ia, Spanish -ez names, enclitic pronoun fragments, and -ula/-ulo endings
have negative responses after accents. Other short continuations receive
only a small negative response. Familiar English derivational suffixes
supply smaller baselines.
The values are rounded training means; most other responses are left out.
"""
import unicodedata

READS = ()

ENGLISH_SUFFIXES = {
    'ular': 0.15,
    'ish': 0.06,
    'hood': 0.31,
    'ary': -0.06,
    'ity': -0.05,
    'ist': -0.04,
    'ese': -0.11,
}
UNACCENTED_LATIN = {
    'ica': 0.38,
    'ico': 0.17,
    'ima': 0.14,
    'ona': 0.15,
    'itas': 0.18,
}


def response(s, distance):
    if not (s.isascii() and s.isalpha()):
        return 0.0
    lower = s.lower()
    value = UNACCENTED_LATIN.get(lower, 0.0)
    if s.islower():
        value += ENGLISH_SUFFIXES.get(s, 0.0)
    if distance > 2:
        return value
    if len(s) <= 5:
        if lower.endswith(('io', 'ios', 'eo', 'eos')):
            return -0.62
        if lower.endswith(('ia', 'ias', 'ea', 'eas')):
            return -0.32
        if lower.endswith(('ica', 'ico')):
            return -0.36
        if lower.endswith(('icas', 'icos')):
            return -0.22
        if lower.endswith(('ula', 'ulo', 'ulas', 'ulos')):
            return -0.45
        if lower.endswith('ez'):
            return -0.42
        if lower in {'ase', 'ose', 'ola', 'olo', 'ole', 'ome', 'elo', 'ela'}:
            return -0.49
        if lower in {'ima', 'imo'}:
            return -0.41
        if lower in {'ric', 'nic', 'lic', 'mic', 'isis'}:
            return -0.63
        if lower == 'ise':
            return -0.36
    if len(s) == 1:
        return -0.05
    return -0.10 if len(s) <= 5 else -0.06


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    distance = carry[1] if carry is not None and carry[0] == doc else 99
    value = response(s, distance)
    for c in s:
        if c.isalpha() or unicodedata.category(c).startswith('M'):
            d = unicodedata.normalize('NFD', c)
            accent = (d[0].lower() in 'aeiou' and
                      any(mark in d for mark in '\u0300\u0301\u0302'))
            distance = 0 if accent else min(99, distance + 1)
        else:
            distance = 99
    return (doc, distance), value
